    this.lights.push({ x: 2600, y: 1470, r: 300, color: [255, 196, 118], intensity: 0.66, flicker: 0.03 });
    this.lights.push({ x: 3030, y: 1480, r: 270, color: [255, 188, 112], intensity: 0.6, flicker: 0.04 });
    this.lights.push({ x: 3140, y: 1850, r: 180, color: [255, 176, 100], intensity: 0.42, flicker: 0.06 });
    this.lights.push({ x: 700, y: 1180, r: 250, color: [186, 210, 255], intensity: 0.5, flicker: 0.28 });
    this.lights.push({ x: 2180, y: 660, r: 180, color: [255, 214, 150], intensity: 0.45, flicker: 0.02 });
    for (const lx of [420, 1200, 2380, 3160]) this.lights.push({ x: lx, y: 468, r: 235, color: [255, 189, 110], intensity: 0.55, flicker: 0.12 });
    this.lights.push({ x: 1750, y: 430, r: 150, color: [255, 120, 80], intensity: 0.3, flicker: 0.3 });

    // spawn beacon points (used for ambient direction / minimap)
    this.spawns = [
      [180, 480], [3500, 640], [3400, 2300], [1750, 2490], [130, 2150], [2050, 120],
      [2900, 800], [500, 560], [1350, 1150], [2380, 2180], [900, 1600], [3000, 1950],
    ];
  }

  addProp(x, y, w, h, type) {
    const prop = { x, y, w, h, type };
    this.props.push(prop);
    if (!['rug'].includes(type)) this.solids.push(prop);
    return prop;
  }

  generateForest() {
    const rng = this.rng;
    const blocked = (x, y, pad) => {
      if (x < 34 || y < 34 || x > MAP.w - 34 || y > MAP.h - 34) return true;
      if (y < 490) return true;
      if (dist2(x, y, CAMPFIRE.x, CAMPFIRE.y) < 255 * 255) return true;
      for (const b of BUILDINGS) {
        if (x > b.x - pad && x < b.x + b.w + pad && y > b.y - pad && y < b.y + b.h + pad) return true;
      }
      const px = (x - POND.x) / (POND.rx + 80), py = (y - POND.y) / (POND.ry + 80);
      if (px * px + py * py < 1) return true;
      for (const p of this.props) if (p.type === 'log' && x > p.x - 40 && x < p.x + p.w + 40 && y > p.y - 40 && y < p.y + p.h + 40) return true;
      return false;
    };

    // border forest ring (dense)
    for (let i = 0; i < 150; i++) {
      const side = (rng() * 4) | 0;
      let x, y;
      if (side === 0) { x = 20 + rng() * (MAP.w - 40); y = 10 + rng() * 120; }
      else if (side === 1) { x = 20 + rng() * (MAP.w - 40); y = MAP.h - 20 - rng() * 100; }
      else if (side === 2) { x = 10 + rng() * 110; y = rng() * MAP.h; }
      else { x = MAP.w - 10 - rng() * 110; y = rng() * MAP.h; }
      if (y < 500 && y > 200) y += 300;
      this.addTree(x, y, rng);
    }

    let tries = 0, count = 0;
    while (count < 285 && tries < 6000) {
      tries++;
      const x = 80 + rng() * (MAP.w - 160);
      const y = 520 + rng() * (MAP.h - 610);
      if (blocked(x, y, 72)) continue;
      if (nearPath(x, y, 76) && rng() > 0.14) continue;
      if (this.trees.some(t => dist2(x, y, t.x, t.y) < 60 * 60)) continue;
      if (zonesNear(x, y)) continue;
      this.addTree(x, y, rng);
      count++;
    }

    // a few hand-placed landmark trees
    for (const [x, y, s] of [[2280, 700, 1.4], [2260, 1680, 1.5], [1120, 720, 1.35], [1480, 1900, 1.3], [2900, 980, 1.25], [610, 1760, 1.4], [3200, 1080, 1.2]]) {
      this.addTree(x, y, mulberry32((x * y) | 0), s);
    }
  }

  addTree(x, y, rng, forceScale) {
    const type = rng() < 0.42 ? 'pine' : 'oak';
    const scale = forceScale || (0.78 + rng() * 0.66);
    const tree = {
      x, y, type, scale,
      r: (type === 'pine' ? 40 : 46) * scale,
      trunk: 12 * scale,
      tint: rng(),
      phase: rng() * TAU,
      sway: type === 'pine' ? 0.008 : 0.014,
    };
    this.trees.push(tree);
    this.solids.push({ x: x - tree.trunk, y: y - tree.trunk * 0.8, w: tree.trunk * 2, h: tree.trunk * 1.6, mat: 'trunk', tree: true });
  }

  generateDetails() {
    const rng = this.rng;
    for (let i = 0; i < 130; i++) {
      const x = 70 + rng() * (MAP.w - 140), y = 520 + rng() * (MAP.h - 590);
      if (nearPath(x, y, 54)) continue;
      if (y < 500) continue;
      if (this.trees.some(t => dist2(x, y, t.x, t.y) < 40 * 40)) continue;
      if (FLOOR_RECTS.some(r => pointInRect(x, y, r))) continue;
      if (dist2(x, y, CAMPFIRE.x, CAMPFIRE.y) < 190 * 190) continue;
      this.bushes.push({ x, y, r: 12 + rng() * 17, tint: rng(), type: rng() < 0.3 ? 'fern' : 'bush' });
    }
    for (let i = 0; i < 46; i++) {
      const x = 80 + rng() * (MAP.w - 160), y = 540 + rng() * (MAP.h - 620);
      if (nearPath(x, y, 70) || FLOOR_RECTS.some(r => pointInRect(x, y, r))) continue;
      const r = 11 + rng() * 18;
      this.rocks.push({ x, y, r, tint: rng() });
      this.solids.push({ x: x - r * .7, y: y - r * .5, w: r * 1.4, h: r, mat: 'rock' });
    }
    // scattered debris along the road
    for (let i = 0; i < 34; i++) {
      this.blood.push({ x: 60 + rng() * (MAP.w - 120), y: 270 + rng() * 230, r: 3 + rng() * 12, a: 0.25 + rng() * 0.3, seed: rng() });
    }
    // old corpses
    for (const [x, y, a] of [[800, 405, 1.1], [1580, 372, -0.6], [2820, 410, 2.4], [2180, 1520, 0.3], [1120, 1250, 2.1], [2000, 1760, -1.2]]) {
      this.corpses.push({ x, y, a, tint: rng() });
    }
  }

  makeMotes() {
    const rng = mulberry32(7733);
    for (let i = 0; i < 90; i++) {
      this.motes.push({ x: rng() * 1200, y: rng() * 800, r: 0.7 + rng() * 1.4, s: 0.15 + rng() * 0.5, p: rng() * TAU, glow: rng() < 0.3 });
    }
  }

  // =============== ground ===============
  makeGround() {
    const c = document.createElement('canvas');
    c.width = MAP.w; c.height = MAP.h;
    const x = c.getContext('2d');
    const rng = mulberry32(99117);
    // base
    const base = x.createLinearGradient(0, 0, MAP.w, MAP.h);
    base.addColorStop(0, '#1c2618'); base.addColorStop(0.45, '#182114'); base.addColorStop(1, '#131b12');
    x.fillStyle = base; x.fillRect(0, 0, MAP.w, MAP.h);

    // broad organic patches
    for (let i = 0; i < 240; i++) {
      const px = rng() * MAP.w, py = rng() * MAP.h, r = 40 + rng() * 190;
      x.globalAlpha = 0.05 + rng() * 0.08;
      x.fillStyle = ['#2c3a22', '#121a10', '#332d1d', '#25301c', '#1b2416'][(rng() * 5) | 0];
      x.beginPath(); x.ellipse(px, py, r, r * (0.4 + rng() * 0.7), rng() * TAU, 0, TAU); x.fill();
    }
    x.globalAlpha = 1;

    // yard / clearing gravel
    this.paintBlob(x, 2840, 2000, 500, 260, '#3a352a', 0.55);
    this.paintBlob(x, 1750, 1420, 260, 220, '#3d3526', 0.85);
    this.paintBlob(x, 880, 1935, 320, 120, '#2a2e1b', 0.5);

    // dirt paths
    for (const path of PATHS) this.paintPath(x, path, 110, '#2f2a20', '#453b29');
    this.paintPath(x, [[1750, 1420], [1715, 1200], [1660, 980], [1640, 760], [1700, 500]], 44, '#2c281e', '#3b3425');

    // road
    this.paintRoad(x, rng);

    // pond
    this.paintPond(x, rng);

    // building floors
    this.paintBuildingFloors(x, rng);

    // grass detail
    for (let i = 0; i < 7200; i++) {
      const px = rng() * MAP.w, py = 470 + rng() * (MAP.h - 470);
      if (py < 500) continue;
      if (FLOOR_RECTS.some(r => pointInRect(px, py, r))) continue;
      if (nearPath(px, py, 48)) continue;
      const pxn = (px - POND.x) / POND.rx, pyn = (py - POND.y) / POND.ry;
      if (pxn * pxn + pyn * pyn < 1) continue;
      const h = 3 + rng() * 8;
      x.strokeStyle = ['#39481f', '#2f421d', '#44531f', '#28371a', '#4a4a22'][(rng() * 5) | 0];
      x.globalAlpha = 0.35 + rng() * 0.4;
      x.lineWidth = 1;
      x.beginPath();
      x.moveTo(px, py); x.lineTo(px + (rng() - .5) * 4, py - h);
      if (rng() < .5) { x.moveTo(px + 2, py); x.lineTo(px + 4, py - h * .7); }
      x.stroke();
    }
    x.globalAlpha = 1;

    // little flowers / mushrooms
    for (let i = 0; i < 190; i++) {
      const px = 100 + rng() * (MAP.w - 200), py = 540 + rng() * (MAP.h - 600);
      if (nearPath(px, py, 34) || FLOOR_RECTS.some(r => pointInRect(px, py, r))) continue;
      if (rng() < 0.55) { x.fillStyle = 'rgba(190,185,120,.7)'; x.fillRect(px, py, 1.6, 1.6); }
      else { x.fillStyle = 'rgba(120,70,54,.8)'; x.beginPath(); x.arc(px, py, 1.8, 0, TAU); x.fill(); }
    }

    // leaves & twigs
    for (let i = 0; i < 900; i++) {
      const px = 70 + rng() * (MAP.w - 140), py = 520 + rng() * (MAP.h - 580);
      x.fillStyle = ['#4a3c1e', '#5a4522', '#332c18', '#3e3d22'][(rng() * 4) | 0];
      x.globalAlpha = 0.25 + rng() * 0.35;
      x.save(); x.translate(px, py); x.rotate(rng() * TAU);
      x.fillRect(0, 0, 2 + rng() * 4, 1 + rng() * 1.5);
      x.restore();
    }
    x.globalAlpha = 1;

    // old blood
    for (const b of this.blood) {
      x.fillStyle = `rgba(58,18,14,${b.a})`;
      x.beginPath(); x.ellipse(b.x, b.y, b.r, b.r * 0.6, b.seed * TAU, 0, TAU); x.fill();
    }
    // corpses
    for (const co of this.corpses) this.paintCorpse(x, co);

    this.ground = c;
  }

  paintBlob(x, cx, cy, rx, ry, color, alpha) {
    x.save();
    x.globalAlpha = alpha;
    x.fillStyle = color;
    x.beginPath();
    for (let i = 0; i <= 26; i++) {
      const a = (i / 26) * TAU;
      const n = 0.82 + Math.sin(a * 3 + cx) * 0.09 + Math.sin(a * 7 + cy) * 0.05;
      const px = cx + Math.cos(a) * rx * n, py = cy + Math.sin(a) * ry * n;
      i ? x.lineTo(px, py) : x.moveTo(px, py);
    }
    x.closePath(); x.fill(); x.restore();
  }

  paintPath(x, pts, width, outer, inner) {
    x.save();
    x.lineCap = 'round'; x.lineJoin = 'round';
    for (let pass = 0; pass < 3; pass++) {
      x.beginPath(); x.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) x.lineTo(pts[i][0], pts[i][1]);
      x.lineWidth = width - pass * 17;
      x.strokeStyle = pass === 0 ? outer : pass === 1 ? inner : 'rgba(90,78,52,.32)';
      x.globalAlpha = pass === 2 ? 0.5 : 1;
      x.stroke();
    }
    x.restore();
  }

  paintRoad(x, rng) {
    x.fillStyle = '#232722'; x.fillRect(0, 250, MAP.w, 190);
    x.fillStyle = '#2c302a'; x.fillRect(0, 240, MAP.w, 16);
    x.fillRect(0, 434, MAP.w, 30);
    x.fillStyle = 'rgba(180,175,140,.28)';
    for (let i = 0; i < 28; i++) x.fillRect(30 + i * 130, 344, 62, 4);
    x.fillStyle = 'rgba(90,88,74,.35)'; x.fillRect(0, 250, MAP.w, 3);
    // cracks
    x.strokeStyle = 'rgba(10,12,10,.55)'; x.lineWidth = 1.2;
    for (let i = 0; i < 90; i++) {
      const px = rng() * MAP.w, py = 255 + rng() * 180;
      x.beginPath(); x.moveTo(px, py);
      x.lineTo(px + (rng() - .5) * 36, py + (rng() - .5) * 22);
      if (rng() < .4) x.lineTo(px + (rng() - .5) * 60, py + (rng() - .5) * 30);
      x.stroke();
    }
    // rust patches
    for (let i = 0; i < 26; i++) {
      x.fillStyle = 'rgba(60,45,30,.16)';
      x.beginPath(); x.ellipse(rng() * MAP.w, 270 + rng() * 160, 30 + rng() * 60, 14 + rng() * 30, 0, 0, TAU); x.fill();
    }
    // crosswalk near kiosk
    x.fillStyle = 'rgba(190,188,160,.20)';
    for (let i = 0; i < 7; i++) x.fillRect(1980 + i * 26, 250, 13, 190);
  }

  paintPond(x, rng) {
    const { x: cx, y: cy, rx, ry } = POND;
    // muddy shore
    x.save();
    x.fillStyle = '#2b2a1c'; x.beginPath(); x.ellipse(cx, cy, rx + 26, ry + 22, 0, 0, TAU); x.fill();
    x.fillStyle = '#33301f'; x.beginPath(); x.ellipse(cx, cy, rx + 10, ry + 9, 0, 0, TAU); x.fill();
    // water
    const wg = x.createRadialGradient(cx - 50, cy - 40, 20, cx, cy, rx);
    wg.addColorStop(0, '#223b38'); wg.addColorStop(0.55, '#1a2d2c'); wg.addColorStop(1, '#111d1d');
    x.fillStyle = wg; x.beginPath(); x.ellipse(cx, cy, rx, ry, 0, 0, TAU); x.fill();
    // reflections
    x.globalAlpha = 0.16; x.strokeStyle = '#9fb7a4'; x.lineWidth = 1;
    for (let i = 0; i < 42; i++) {
      const px = cx - rx * .8 + rng() * rx * 1.6;
      const py = cy - ry * .8 + rng() * ry * 1.6;
      if (((px - cx) / rx) ** 2 + ((py - cy) / ry) ** 2 > .8) continue;
      x.beginPath(); x.moveTo(px, py); x.lineTo(px + 10 + rng() * 26, py); x.stroke();
    }
    x.globalAlpha = 0.5; x.fillStyle = '#3b4a2d';
    for (let i = 0; i < 60; i++) {
      const a = rng() * TAU, rr = 0.9 + rng() * .13;
      const px = cx + Math.cos(a) * rx * rr, py = cy + Math.sin(a) * ry * rr;
      x.strokeStyle = '#556138'; x.lineWidth = 1.3;
      x.beginPath(); x.moveTo(px, py); x.lineTo(px + (rng() - .5) * 5, py - 10 - rng() * 14); x.stroke();
    }
    x.restore();
  }

  paintBuildingFloors(x, rng) {
    const g = BUILDINGS[0];
    // wood floor
    x.fillStyle = '#3a2c20'; x.fillRect(g.x + 20, g.y + 20, g.w - 40, g.h - 40);
    for (let y = g.y + 24; y < g.y + g.h - 20; y += 22) {
      x.fillStyle = 'rgba(16,10,6,.35)'; x.fillRect(g.x + 20, y, g.w - 40, 1.4);
      for (let px = g.x + 20; px < g.x + g.w - 20; px += 150 + rng() * 80) {
        x.fillStyle = 'rgba(20,13,8,.3)'; x.fillRect(px, y, 1, 21);
      }
    }
    for (let i = 0; i < 80; i++) {
      x.fillStyle = `rgba(90,66,40,${0.05 + rng() * .08})`;
      x.fillRect(g.x + 24 + rng() * (g.w - 60), g.y + 24 + rng() * (g.h - 60), 10 + rng() * 60, 1.5 + rng() * 3);
    }
    // kitchen tile
    x.save(); x.beginPath(); x.rect(2876, 1204, 360, 448); x.clip();
    x.fillStyle = '#3a3b33'; x.fillRect(2876, 1204, 360, 448);
    for (let i = 0; i < 11; i++) for (let j = 0; j < 13; j++) {
      x.fillStyle = (i + j) % 2 ? 'rgba(210,205,180,.035)' : 'rgba(0,0,0,.06)';
      x.fillRect(2876 + i * 34, 1204 + j * 35, 32, 33);
    }
    x.restore();
    // bunker
    const b = BUILDINGS[1];
    x.fillStyle = '#36382f'; x.fillRect(b.x + 20, b.y + 20, b.w - 40, b.h - 40);
    for (let i = 0; i < 40; i++) {
      x.fillStyle = `rgba(0,0,0,${.04 + rng() * .1})`;
      x.beginPath(); x.ellipse(b.x + 30 + rng() * (b.w - 60), b.y + 30 + rng() * (b.h - 60), 4 + rng() * 20, 3 + rng() * 12, 0, 0, TAU); x.fill();
    }
    // kiosk tile
    const k = BUILDINGS[2];
    x.fillStyle = '#3c382c'; x.fillRect(k.x + 18, k.y + 18, k.w - 36, k.h - 36);
    for (let i = 0; i < 8; i++) for (let j = 0; j < 7; j++) {
      x.strokeStyle = 'rgba(0,0,0,.14)'; x.strokeRect(k.x + 18 + i * 24, k.y + 18 + j * 24, 24, 24);
    }
    // doorway thresholds
    x.fillStyle = 'rgba(80,70,52,.35)';
    x.fillRect(2450, 1460, 26, 110);
    x.fillRect(2780, 1916, 110, 26);
    x.fillRect(958, 1150, 24, 90);
    x.fillRect(2140, 742, 70, 20);
  }

  paintCorpse(x, co) {
    x.save(); x.translate(co.x, co.y); x.rotate(co.a);
    x.fillStyle = 'rgba(6,8,6,.35)'; x.beginPath(); x.ellipse(3, 5, 22, 10, 0, 0, TAU); x.fill();
    x.fillStyle = co.tint < .5 ? '#46483b' : '#4a3d33';
    x.beginPath(); x.ellipse(0, 0, 17, 8, 0, 0, TAU); x.fill();
    x.fillStyle = '#6b6856'; x.beginPath(); x.arc(16, -2, 6, 0, TAU); x.fill();
    x.strokeStyle = '#3c3a2f'; x.lineWidth = 4; x.lineCap = 'round';
    x.beginPath(); x.moveTo(-10, -6); x.lineTo(-24, -14); x.moveTo(-10, 6); x.lineTo(-22, 12); x.stroke();
    x.fillStyle = 'rgba(70,20,15,.5)'; x.beginPath(); x.ellipse(4, 3, 16, 7, .3, 0, TAU); x.fill();
    x.restore();
  }

  // =============== drawing ===============
  drawGround(ctx, cam, vw, vh) {
    const sx = clamp(cam.x - vw / 2 - 20, 0, MAP.w);
    const sy = clamp(cam.y - vh / 2 - 20, 0, MAP.h);
    const sw = Math.min(vw + 40, MAP.w - sx), sh = Math.min(vh + 40, MAP.h - sy);
    const zoom = cam.zoom;
    // ground image drawn in screen coordinates for crispness
    ctx.drawImage(this.ground, sx, sy, sw, sh,
      (sx - (cam.x - vw / 2)) * zoom, (sy - (cam.y - vh / 2)) * zoom, sw * zoom, sh * zoom);
  }

  drawWater(ctx, t) {
    const { x, y, rx, ry } = POND;
    ctx.save();
    ctx.globalAlpha = 0.25;
    ctx.strokeStyle = '#9eb9a6'; ctx.lineWidth = 1;
    for (let i = 0; i < 9; i++) {
      const p = (t * 0.12 + i * 0.37) % 1;
      const py = y - ry * 0.55 + p * ry * 1.1;
      const w = Math.sin(p * Math.PI) * rx * 0.6;
      ctx.globalAlpha = Math.sin(p * Math.PI) * 0.13;
      ctx.beginPath(); ctx.ellipse(x + Math.sin(i * 2 + t * .3) * 24, py, w * 0.25, 2, 0, 0, TAU); ctx.stroke();
    }
    ctx.restore();
  }

  drawStructures(ctx, t) {
    // fences first
    for (const f of this.fences) this.drawFence(ctx, f);
    // props
    for (const p of this.props) {
      if (p.type === 'rug') this.drawRug(ctx, p);
    }
    for (const p of this.props) if (p.type !== 'rug') this.drawProp(ctx, p);
    // cars
    for (const c of this.cars) this.drawCar(ctx, c);
  }

  drawFence(ctx, f) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.35)'; ctx.fillRect(f.x + 4, f.y + 5, f.w, f.h);
    ctx.fillStyle = '#5b5340'; ctx.fillRect(f.x, f.y, f.w, f.h);
    ctx.fillStyle = '#7a7057'; ctx.fillRect(f.x, f.y, f.w, 3);
    ctx.fillStyle = '#3d372b';
    const along = f.w > f.h;
    const n = Math.floor((along ? f.w : f.h) / 16);
    for (let i = 0; i < n; i++) {
      if (along) ctx.fillRect(f.x + i * 16, f.y, 2, f.h); else ctx.fillRect(f.x, f.y + i * 16, f.w, 2);
    }
    ctx.restore();
  }

  drawRug(ctx, p) {
    ctx.save();
    ctx.fillStyle = '#4a2f24'; ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.strokeStyle = 'rgba(160,120,70,.3)'; ctx.lineWidth = 3; ctx.strokeRect(p.x + 8, p.y + 8, p.w - 16, p.h - 16);
    ctx.strokeStyle = 'rgba(20,12,8,.5)'; ctx.lineWidth = 1; ctx.strokeRect(p.x + 14, p.y + 14, p.w - 28, p.h - 28);
    ctx.restore();
  }

  drawProp(ctx, p) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.4)';
    ctx.fillRect(p.x + 5, p.y + 6, p.w, p.h);
    switch (p.type) {
      case 'bar':
        ctx.fillStyle = '#4b3724'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = '#6b4f33'; ctx.fillRect(p.x + 3, p.y + 3, p.w - 6, p.h - 6);
        ctx.fillStyle = 'rgba(0,0,0,.25)';
        for (let y = p.y + 12; y < p.y + p.h; y += 26) ctx.fillRect(p.x + 4, y, p.w - 8, 2);
        ctx.fillStyle = '#7f5f40'; ctx.fillRect(p.x, p.y, p.w, 5);
        break;
      case 'table':
        ctx.fillStyle = '#5a4229'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = '#7a5b3a'; ctx.fillRect(p.x + 3, p.y + 3, p.w - 6, p.h - 6);
        ctx.fillStyle = 'rgba(0,0,0,.2)'; ctx.fillRect(p.x + 10, p.y + 10, p.w - 20, p.h - 20);
        break;
      case 'counter':
        ctx.fillStyle = '#4a4c40'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = '#6d6e5e'; ctx.fillRect(p.x + 2, p.y + 2, p.w - 4, 6);
        break;
      case 'shelf':
        ctx.fillStyle = '#3d392c'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = 'rgba(20,16,10,.7)';
        for (let i = 0; i < 4; i++) ctx.fillRect(p.x + 3, p.y + 8 + i * (p.h / 4), p.w - 6, 3);
        ctx.fillStyle = 'rgba(160,140,80,.35)';
        for (let i = 0; i < 6; i++) ctx.fillRect(p.x + 6 + (i * 7) % (p.w - 12), p.y + 12 + (i * 23) % (p.h - 20), 5, 8);
        break;
      case 'crate':
        ctx.fillStyle = '#5a4528'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.strokeStyle = '#2e2414'; ctx.lineWidth = 2; ctx.strokeRect(p.x + 2, p.y + 2, p.w - 4, p.h - 4);
        ctx.beginPath(); ctx.moveTo(p.x + 3, p.y + 3); ctx.lineTo(p.x + p.w - 3, p.y + p.h - 3);
        ctx.moveTo(p.x + p.w - 3, p.y + 3); ctx.lineTo(p.x + 3, p.y + p.h - 3); ctx.stroke();
        break;
      case 'sandbag':
        ctx.fillStyle = '#665f45';
        for (let i = 0; i < Math.max(2, Math.round(p.w / 34)); i++) {
          roundedRect(ctx, p.x + i * (p.w / 4), p.y, p.w / 4 + 5, p.h / 2, 8); ctx.fill();
          roundedRect(ctx, p.x + 8 + i * (p.w / 4), p.y + p.h / 2, p.w / 4 + 5, p.h / 2, 8); ctx.fill();
        }
        break;
      case 'log':
        ctx.fillStyle = '#4c3d27'; roundedRect(ctx, p.x, p.y, p.w, p.h, p.h / 2); ctx.fill();
        ctx.fillStyle = '#5e4c31'; roundedRect(ctx, p.x + 2, p.y + 2, p.w - 4, p.h - 8, p.h / 2); ctx.fill();
        ctx.fillStyle = '#3a2e1d'; ctx.beginPath(); ctx.ellipse(p.x + p.w - 3, p.y + p.h / 2, 4, p.h / 2 - 3, 0, 0, TAU); ctx.fill();
        break;
      case 'bunk':
        ctx.fillStyle = '#4b4c3c'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = '#6c6850'; ctx.fillRect(p.x + 2, p.y + 2, p.w - 4, p.h - 4);
        ctx.fillStyle = '#7d7a5e'; ctx.fillRect(p.x + 6, p.y + 5, p.w - 12, 8);
        break;
      case 'locker':
        ctx.fillStyle = '#3e423c'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.strokeStyle = '#252822'; ctx.strokeRect(p.x + 2, p.y + 2, p.w - 4, p.h - 4);
        ctx.fillStyle = '#767a6c'; ctx.fillRect(p.x + p.w - 10, p.y + p.h / 2 - 8, 3, 16);
        break;
      case 'desk':
        ctx.fillStyle = '#46382a'; ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = '#5d4b36'; ctx.fillRect(p.x + 2, p.y + 2, p.w - 4, p.h - 4);
        ctx.fillStyle = '#a2a08a'; ctx.fillRect(p.x + 12, p.y + 8, 24, 18);
        break;
    }
    ctx.restore();
  }

  drawCar(ctx, c) {
    ctx.save();
    ctx.translate(c.x + c.w / 2, c.y + c.h / 2);
    ctx.rotate(c.rot);
    const w = c.w, h = c.h;
    ctx.fillStyle = 'rgba(0,0,0,.45)';
    roundedRect(ctx, -w / 2 + 5, -h / 2 + 7, w, h, 16); ctx.fill();
    ctx.fillStyle = c.color;
    roundedRect(ctx, -w / 2, -h / 2, w, h, 17); ctx.fill();
    ctx.fillStyle = 'rgba(20,24,22,.85)';
    roundedRect(ctx, -w * .22, -h * .40, w * .40, h * .8, 6); ctx.fill();
    ctx.fillStyle = 'rgba(130,150,145,.20)';
    roundedRect(ctx, -w * .17, -h * .34, w * .26, h * .68, 4); ctx.fill();
    ctx.fillStyle = '#1b1d1a';
    ctx.fillRect(-w * .34, -h / 2 - 2, 26, 5); ctx.fillRect(w * .18, -h / 2 - 2, 26, 5);
    ctx.fillRect(-w * .34, h / 2 - 3, 26, 5); ctx.fillRect(w * .18, h / 2 - 3, 26, 5);
    ctx.fillStyle = 'rgba(120,110,80,.5)';
    ctx.fillRect(-w / 2 + 6, -h / 2 + 4, w - 12, 2);
    if (c.type === 'police') {
      ctx.fillStyle = '#2b3a55'; ctx.fillRect(-w * .12, -h / 2 + 2, w * .24, h * .94);
      ctx.fillStyle = '#ccb96a'; ctx.fillRect(-w * .35, -h / 2 + 3, w * .7, 2);
      ctx.fillStyle = 'rgba(80,110,160,.8)'; ctx.fillRect(-6, -h / 2 + 1, 12, 5);
    }
    if (c.type === 'van') { ctx.fillStyle = 'rgba(90,88,70,.35)'; ctx.fillRect(-w * .28, -h / 2 + 3, w * .56, h - 6); }
    // rust
    ctx.fillStyle = 'rgba(70,48,25,.35)';
    ctx.beginPath(); ctx.ellipse(w * .3, h * .2, 14, 6, .3, 0, TAU); ctx.fill();
    ctx.restore();
  }

  drawTree(ctx, tree, t) {
    const { x, y, type, scale, tint } = tree;
    const sway = Math.sin(t * 0.7 + tree.phase) * tree.sway * 10 * scale;
    ctx.save();
    // trunk shadow
    ctx.fillStyle = 'rgba(0,0,0,.3)';
    ctx.beginPath(); ctx.ellipse(x + 14, y + 8, 24 * scale, 11 * scale, 0, 0, TAU); ctx.fill();
    if (type === 'pine') {
      const r = tree.r;
      const layers = [
        { rr: r * 1.0, c: tint > .5 ? '#1d2c1a' : '#22311c', off: 0 },
        { rr: r * .74, c: tint > .5 ? '#26371f' : '#2b3c23', off: -r * .12 },
        { rr: r * .48, c: '#344826', off: -r * .24 },
        { rr: r * .24, c: '#41552d', off: -r * .34 },
      ];
      for (const L of layers) {
        ctx.fillStyle = L.c;
        ctx.beginPath();
        const cx = x + sway * (1 + L.off / r), cy = y - r * .28 + L.off;
        for (let i = 0; i <= 22; i++) {
          const a = (i / 22) * TAU;
          const spike = 0.72 + Math.cos(a * 7) * 0.22 + Math.sin(a * 3 + tree.phase) * 0.1;
          const px = cx + Math.cos(a) * L.rr * spike;
          const py = cy + Math.sin(a) * L.rr * spike * 0.92;
          i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
        }
        ctx.closePath(); ctx.fill();
      }
      // moon rim
      ctx.strokeStyle = 'rgba(140,170,120,.12)'; ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.arc(x - r * .12 + sway, y - r * .45, r * .58, Math.PI * 1.05, Math.PI * 1.7); ctx.stroke();
      // trunk top
      ctx.fillStyle = '#3a2b1b'; ctx.beginPath(); ctx.arc(x, y, tree.trunk * .8, 0, TAU); ctx.fill();
    } else {
      const r = tree.r;
      const blobs = [
        { dx: -r * .28, dy: -r * .14, rr: r * .62, c: '#26341d' },
        { dx: r * .3, dy: -r * .08, rr: r * .56, c: '#22301a' },
        { dx: 0, dy: -r * .34, rr: r * .60, c: '#2c3c21' },
        { dx: -r * .06, dy: -r * .1, rr: r * .54, c: '#334525' },
        { dx: r * .16, dy: -r * .38, rr: r * .35, c: '#3b4d29' },
        { dx: -r * .34, dy: -r * .34, rr: r * .30, c: '#314226' },
      ];
      ctx.fillStyle = 'rgba(0,0,0,.3)';
      ctx.beginPath(); ctx.ellipse(x + 16, y + 6, r * .8, r * .42, 0, 0, TAU); ctx.fill();
      for (const b of blobs) {
        ctx.fillStyle = b.c;
        ctx.beginPath(); ctx.ellipse(x + b.dx + sway, y - r * .3 + b.dy, b.rr, b.rr * .92, 0, 0, TAU); ctx.fill();
      }
      // highlight leaves
      ctx.fillStyle = 'rgba(110,140,80,.16)';
      for (let i = 0; i < 7; i++) {
        const a = i * 2.1 + tree.phase;
        ctx.beginPath(); ctx.ellipse(x + Math.cos(a) * r * .42 + sway, y - r * .42 + Math.sin(a) * r * .25, r * .16, r * .10, a, 0, TAU); ctx.fill();
      }
      ctx.fillStyle = '#3a2b1b'; ctx.beginPath(); ctx.arc(x, y, tree.trunk * .85, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.beginPath(); ctx.arc(x + 2, y + 2, tree.trunk * .6, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  drawBush(ctx, b) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.25)';
    ctx.beginPath(); ctx.ellipse(b.x + 4, b.y + 5, b.r, b.r * .7, 0, 0, TAU); ctx.fill();
    const base = b.type === 'fern' ? '#2b4122' : '#2f4022';
    ctx.fillStyle = base;
    ctx.beginPath(); ctx.ellipse(b.x, b.y, b.r, b.r * .78, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = b.tint > .5 ? '#3d5129' : '#374a26';
    for (let i = 0; i < 5; i++) {
      const a = i * 1.7 + b.tint * 5;
      ctx.beginPath(); ctx.ellipse(b.x + Math.cos(a) * b.r * .4, b.y + Math.sin(a) * b.r * .3, b.r * .45, b.r * .3, a, 0, TAU); ctx.fill();
    }
    if (b.type === 'fern') {
      ctx.strokeStyle = '#4d6234'; ctx.lineWidth = 1;
      for (let i = 0; i < 6; i++) {
        const a = -Math.PI / 2 + (i - 2.5) * .35;
        ctx.beginPath(); ctx.moveTo(b.x, b.y); ctx.lineTo(b.x + Math.cos(a) * b.r * 1.2, b.y + Math.sin(a) * b.r * .9); ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawRock(ctx, rock) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.3)';
    ctx.beginPath(); ctx.ellipse(rock.x + 4, rock.y + 4, rock.r, rock.r * .7, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = rock.tint > .5 ? '#4b4c42' : '#41443c';
    ctx.beginPath();
    for (let i = 0; i <= 9; i++) {
      const a = (i / 9) * TAU, rr = rock.r * (0.82 + Math.sin(i * 2.7 + rock.tint * 9) * .16);
      const px = rock.x + Math.cos(a) * rr, py = rock.y + Math.sin(a) * rr * .75;
      i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
    }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(150,155,135,.18)';
    ctx.beginPath(); ctx.ellipse(rock.x - rock.r * .2, rock.y - rock.r * .2, rock.r * .45, rock.r * .25, -.4, 0, TAU); ctx.fill();
    ctx.restore();
  }

  // =============== collision ===============
  isBlocked(x, y, r = 14) {
    if (x < 30 + r || y < 30 + r || x > MAP.w - 30 - r || y > MAP.h - 30 - r) return true;
    const px = (x - POND.x) / (POND.rx + r), py = (y - POND.y) / (POND.ry + r);
    if (px * px + py * py < 1) return true;
    for (const s of this.solids) {
      if (s.mat === 'trunk' || s.mat === 'rock') continue;
      if (x + r > s.x && x - r < s.x + s.w && y + r > s.y && y - r < s.y + s.h) return true;
    }
    for (const t of this.trees) if (dist2(x, y, t.x, t.y) < (t.trunk * .9 + r) ** 2) return true;
    for (const rk of this.rocks) if (dist2(x, y, rk.x, rk.y) < (rk.r * .75 + r) ** 2) return true;
    return false;
  }

  moveCircle(ent, dx, dy, r) {
    ent.x += dx;
    for (let pass = 0; pass < 2; pass++) {
      this.resolve(ent, r);
    }
    ent.y += dy;
    for (let pass = 0; pass < 2; pass++) this.resolve(ent, r);
    // world bounds
    ent.x = clamp(ent.x, 34 + r, MAP.w - 34 - r);
    ent.y = clamp(ent.y, 34 + r, MAP.h - 34 - r);
  }

  resolve(ent, r) {
    // pond ellipse
    const ex = (ent.x - POND.x) / (POND.rx + r), ey = (ent.y - POND.y) / (POND.ry + r);
    const ed = ex * ex + ey * ey;
    if (ed < 1 && ed > 0.00001) {
      const k = 1 / Math.sqrt(ed);
      ent.x = POND.x + (ent.x - POND.x) * k;
      ent.y = POND.y + (ent.y - POND.y) * k;
    }
    for (const s of this.solids) {
      const cx = clamp(ent.x, s.x, s.x + s.w);
      const cy = clamp(ent.y, s.y, s.y + s.h);
      const dx = ent.x - cx, dy = ent.y - cy;
      const d2 = dx * dx + dy * dy;
      if (d2 < r * r) {
        if (d2 > 0.0001) {
          const d = Math.sqrt(d2), push = (r - d) / d;
          ent.x += dx * push; ent.y += dy * push;
        } else {
          const left = ent.x - s.x, right = s.x + s.w - ent.x;
          const top = ent.y - s.y, bottom = s.y + s.h - ent.y;
          const m = Math.min(left, right, top, bottom);
          if (m === left) ent.x = s.x - r;
          else if (m === right) ent.x = s.x + s.w + r;
          else if (m === top) ent.y = s.y - r;
          else ent.y = s.y + s.h + r;
        }
      }
    }
    for (const t of this.trees) {
      const rr = t.trunk * .9 + r;
      if (dist2(ent.x, ent.y, t.x, t.y) < rr * rr) {
        const d = Math.hypot(ent.x - t.x, ent.y - t.y) || 0.01;
        ent.x = t.x + (ent.x - t.x) / d * rr;
        ent.y = t.y + (ent.y - t.y) / d * rr;
      }
    }
    for (const rk of this.rocks) {
      const rr = rk.r * .75 + r;
      if (dist2(ent.x, ent.y, rk.x, rk.y) < rr * rr) {
        const d = Math.hypot(ent.x - rk.x, ent.y - rk.y) || 0.01;
        ent.x = rk.x + (ent.x - rk.x) / d * rr;
        ent.y = rk.y + (ent.y - rk.y) / d * rr;
      }
    }
  }

  lineBlocked(x1, y1, x2, y2) {
    const steps = Math.ceil(Math.hypot(x2 - x1, y2 - y1) / 30);
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      if (this.isBlocked(x1 + (x2 - x1) * t, y1 + (y2 - y1) * t, 10)) return true;
    }
    return false;
  }

  insideBuilding(x, y) {
    return BUILDINGS.find(b => x > b.x + 18 && x < b.x + b.w - 18 && y > b.y + 18 && y < b.y + b.h - 18) || null;
  }
}

function zonesNear(x, y) {
  // keep a couple of clearings open for fights
  const zones = [[2350, 900, 190], [900, 1500, 190], [2700, 2200, 200], [1250, 2250, 170], [3200, 1500, 180]];
  return zones.some(([zx, zy, r]) => dist2(x, y, zx, zy) < r * r);
}

export const World = new WorldModel();

import { TAU, angleDiff, clamp, dist, dist2, lerpAngle, norm, rand, roundedRect } from './util.js';
import { World } from './world.js';
import { Audio } from './audio.js';
import { Input } from './input.js';

export const WEAPONS = {
  pistol: { id: 'pistol', name: "RICK'S KARABINER", short: 'PISTOLE', dmg: 26, rate: .17, spread: .028, mag: 14, reload: 1.0, pellets: 1, speed: 1650, reserve: Infinity, kick: 1.5, sound: 'pistol', pierce: 0, crit: .06 },
  shotgun: { id: 'shotgun', name: 'FORSTFLINTE', short: 'SCHROT', dmg: 13, rate: .78, spread: .20, mag: 6, reload: 1.85, pellets: 9, speed: 1400, reserve: 42, kick: 7, sound: 'shotgun', pierce: 0, crit: .03 },
  smg: { id: 'smg', name: 'MP „GARATH“', short: 'MP', dmg: 14, rate: .072, spread: .075, mag: 34, reload: 1.4, pellets: 1, speed: 1500, reserve: 300, kick: 1.1, sound: 'smg', pierce: 0, crit: .05 },
  rifle: { id: 'rifle', name: 'JAGDGEWEHR', short: 'GEWEHR', dmg: 60, rate: .46, spread: .012, mag: 10, reload: 1.7, pellets: 1, speed: 2100, reserve: 70, kick: 5, sound: 'rifle', pierce: 1, crit: .14 },
};

export const ZOMBIE_TYPES = {
  walker: { hp: 64, speed: 56, dmg: 9, r: 15, xp: 12, score: 10, scale: 1, skin: '#8a9272', shirt: '#4b4c3b' },
  runner: { hp: 44, speed: 122, dmg: 7, r: 13, xp: 15, score: 14, scale: .94, skin: '#9a9c7c', shirt: '#553f36' },
  brute: { hp: 340, speed: 43, dmg: 22, r: 25, xp: 52, score: 55, scale: 1.45, skin: '#787f61', shirt: '#3c4638' },
  boss: { hp: 1350, speed: 40, dmg: 32, r: 40, xp: 340, score: 600, scale: 2.1, skin: '#6e7758', shirt: '#2f3a2c' },
};

export class Player {
  constructor(x, y) {
    this.x = x; this.y = y; this.r = 15;
    this.angle = -Math.PI / 2;
    this.walk = 0; this.moving = false;
    this.maxHp = 100; this.hp = 100; this.shield = 0;
    this.speed = 238;
    this.level = 1; this.xp = 0; this.xpNext = 90;
    this.weapons = { pistol: { ...WEAPONS.pistol, mag: 14, reserve: Infinity, owned: true } };
    this.current = 'pistol';
    this.fireCd = 0; this.reloading = 0; this.reloadDuration = 0;
    this.dashCd = 0; this.dashTime = 0; this.dashCdMax = 1.7;
    this.invuln = 0; this.hitFlash = 0; this.muzzle = 0; this.recoil = 0;
    this.damageBuff = 0; this.speedBuff = 0;
    this.upgrades = { damage: 1, fireRate: 1, speed: 1, pierce: 0, crit: 0, dashCd: 1, reload: 1, armor: 0, regen: 0 };
    this.dashDir = { x: 0, y: -1 };
    this.stats = { shots: 0, hits: 0, kills: 0, dmg: 0 };
    this.regenTimer = 0;
  }

  get weapon() { return this.weapons[this.current]; }
  get maxSpeed() { return this.speed * this.upgrades.speed * (this.speedBuff > 0 ? 1.34 : 1); }

  addWeapon(id, game) {
    if (this.weapons[id]) {
      const w = this.weapons[id];
      if (w.reserve !== Infinity) w.reserve += WEAPONS[id].reserve;
      this.current = id;
      game.toast(`<b>${WEAPONS[id].name}</b> · Munition aufgefüllt`);
    } else {
      const base = WEAPONS[id];
      this.weapons[id] = { ...base, mag: base.mag, reserve: base.reserve, owned: true };
      this.current = id;
      game.toast(`<b>${base.name}</b> gefunden`);
      Audio.powerup();
    }
  }

  switchWeapon(id, game) {
    if (!this.weapons[id] || this.current === id) return;
    this.current = id;
    this.reloading = 0;
    this.fireCd = Math.max(this.fireCd, .2);
    game.toast(`${WEAPONS[id].short} AUSGERÜSTET`, 'dog');
  }

  tryReload(game) {
    const w = this.weapon;
    if (this.reloading > 0 || w.mag >= w.magSize) return;
    if (w.reserve <= 0) { Audio.empty(); return; }
    this.reloading = w.reload / this.upgrades.reload;
    this.reloadDuration = this.reloading;
    Audio.reload();
  }

  finishReload() {
    const w = this.weapon;
    const need = w.magSize - w.mag;
    const take = w.reserve === Infinity ? need : Math.min(need, w.reserve);
    w.mag += take;
    if (w.reserve !== Infinity) w.reserve -= take;
    Audio.reloadDone();
  }

  update(dt, game) {
    const t = game.time;
    this.fireCd = Math.max(0, this.fireCd - dt);
    this.dashCd = Math.max(0, this.dashCd - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.muzzle = Math.max(0, this.muzzle - dt);
    this.recoil = Math.max(0, this.recoil - dt * 18);
    this.damageBuff = Math.max(0, this.damageBuff - dt);
    this.speedBuff = Math.max(0, this.speedBuff - dt);
    if (this.upgrades.regen > 0 && this.hp > 0) {
      this.regenTimer += dt;
      if (this.regenTimer > 3) { this.regenTimer = 0; this.hp = Math.min(this.maxHp, this.hp + this.upgrades.regen); }
    }
    if (this.reloading > 0) {
      this.reloading -= dt;
      if (this.reloading <= 0) { this.reloading = 0; this.finishReload(); }
    }

    let mx = 0, my = 0;
    if (Input.down('KeyW') || Input.down('ArrowUp')) my -= 1;
    if (Input.down('KeyS') || Input.down('ArrowDown')) my += 1;
    if (Input.down('KeyA') || Input.down('ArrowLeft')) mx -= 1;
    if (Input.down('KeyD') || Input.down('ArrowRight')) mx += 1;
    mx += Input.pad.moveX + Input.touch.moveX;
    my += Input.pad.moveY + Input.touch.moveY;
    const ml = Math.hypot(mx, my);
    if (ml > 1) { mx /= ml; my /= ml; }
    this.moving = ml > .08;

    // aim
    const aim = game.getAim(this);
    if (aim) this.angle = aim;

    // start dash
    const dashPressed = Input.hit('ShiftLeft') || Input.hit('ShiftRight') || Input.hit('Space') || Input.touch.dash || Input.pad.dash;
    if (dashPressed && this.dashCd <= 0 && this.dashTime <= 0) {
      this.dashTime = .18;
      this.dashCd = this.dashCdMax * this.upgrades.dashCd;
      this.invuln = Math.max(this.invuln, .34);
      this.dashDir = this.moving ? norm(mx, my) : { x: Math.cos(this.angle), y: Math.sin(this.angle) };
      Audio.dash();
      game.afterimages.push({ x: this.x, y: this.y, a: this.angle, life: .35 });
      game.shake(3);
    }

    if (this.dashTime > 0) {
      this.dashTime -= dt;
      World.moveCircle(this, this.dashDir.x * 880 * dt, this.dashDir.y * 880 * dt, this.r);
      this.walk += dt * 15;
      if (Math.random() < .7) game.particles.push({ x: this.x + rand(-8, 8), y: this.y + rand(-8, 8), vx: -this.dashDir.x * rand(10, 50), vy: -this.dashDir.y * rand(10, 50), r: rand(2, 5), life: .3, maxLife: .3, color: 'rgba(180,170,140,', type: 'dust', grow: 1.5 });
    } else {
      const sp = this.maxSpeed;
      World.moveCircle(this, mx * sp * dt, my * sp * dt, this.r);
      if (this.moving) this.walk += dt * (6 + sp / 45);
    }

    // footprints
    if (this.moving && Math.random() < dt * 8) {
      game.particles.push({ x: this.x - Math.cos(this.angle) * 6, y: this.y - Math.sin(this.angle) * 6, vx: 0, vy: 0, r: 2.5, life: 1.2, maxLife: 1.2, color: 'rgba(50,45,30,', type: 'foot', fade: true });
    }

    // shooting
    const firing = Input.mouse.down || Input.touch.fire || Input.pad.fire;
    if (firing && this.reloading <= 0 && this.fireCd <= 0 && this.dashTime <= 0) {
      const w = this.weapon;
      if (w.mag <= 0) {
        Audio.empty();
        this.fireCd = .25;
        this.tryReload(game);
      } else {
        this.shoot(game);
      }
    }

    // reload input
    if ((Input.hit('KeyR') || Input.touch.reload || Input.pad.reload) && this.reloading <= 0) this.tryReload(game);

    // weapon switch
    const slots = ['pistol', 'shotgun', 'smg', 'rifle'];
    for (let i = 0; i < 4; i++) if (Input.hit('Digit' + (i + 1))) this.switchWeapon(slots[i], game);
    if (Math.abs(game.scrollDelta) > 0) {
      let idx = slots.indexOf(this.current);
      idx = (idx + (game.scrollDelta > 0 ? 1 : 3)) % 4;
      for (let k = 0; k < 4 && !this.weapons[slots[idx]]; k++) idx = (idx + 1) % 4;
      this.switchWeapon(slots[idx], game);
      game.scrollDelta = 0;
    }
  }

  shoot(game) {
    const w = this.weapon;
    const dmgMul = this.damageBuff > 0 ? 2 : 1;
    this.fireCd = w.rate / this.upgrades.fireRate;
    this.muzzle = .07;
    this.recoil = w.kick;
    w.mag--;
    this.stats.shots++;
    const baseAngle = this.angle + (Math.random() - .5) * this.recoil * .02;
    for (let i = 0; i < w.pellets; i++) {
      const spread = (Math.random() - .5) * w.spread * 2 + (this.moving ? .012 : 0);
      const a = baseAngle + spread;
      const crit = Math.random() < (w.crit + this.upgrades.crit);
      const dmg = w.dmg * this.upgrades.damage * dmgMul * (crit ? 2 : 1);
      game.bullets.push(new Bullet(
        this.x + Math.cos(a) * 24, this.y + Math.sin(a) * 24,
        Math.cos(a) * w.speed, Math.sin(a) * w.speed,
        dmg, w.pierce + this.upgrades.pierce, crit, w.id
      ));
    }
    Audio.shoot(w.sound);
    game.shake(w.kick * .55);
    game.muzzleFlash(this.x + Math.cos(this.angle) * 30, this.y + Math.sin(this.angle) * 30, this.angle, w.id);
    // shell
    const sa = this.angle + Math.PI / 2 + rand(-.3, .3);
    game.particles.push({ x: this.x, y: this.y, vx: Math.cos(sa) * rand(40, 90), vy: Math.sin(sa) * rand(40, 90), r: 2, life: .9, maxLife: .9, color: 'rgba(200,160,70,', type: 'shell', vdamp: 3 });
    // recoil push player a bit
    this.x -= Math.cos(this.angle) * w.kick * .4;
    this.y -= Math.sin(this.angle) * w.kick * .4;
  }

  takeDamage(amount, game) {
    if (this.invuln > 0 || this.hp <= 0) return;
    let dmg = amount;
    if (this.shield > 0) {
      const absorbed = Math.min(this.shield, dmg);
      this.shield -= absorbed; dmg -= absorbed;
      game.ring(this.x, this.y, 30, 'rgba(120,200,225,');
    }
    if (dmg > 0) this.hp -= dmg;
    this.hitFlash = .18;
    this.invuln = .45;
    game.shake(9);
    game.hurtFlash = 1;
    Audio.hurt();
    game.damageNumber(this.x, this.y - 24, `-${Math.round(dmg + (this.shield ? 0 : 0))}`, '#e46a52');
    if (this.hp <= 0) { this.hp = 0; game.onPlayerDown(); }
  }

  heal(n) { this.hp = Math.min(this.maxHp, this.hp + n); }

  draw(ctx, t) {
    const { x, y, angle } = this;
    ctx.save();
    // shadow
    ctx.fillStyle = 'rgba(0,0,0,.42)';
    ctx.beginPath(); ctx.ellipse(x + 3, y + 7, 18, 10, 0, 0, TAU); ctx.fill();
    ctx.translate(x, y);
    if (this.invuln > 0 && Math.floor(t * 30) % 2 === 0) ctx.globalAlpha = .55;
    ctx.rotate(angle);
    const bob = Math.sin(this.walk) * (this.moving ? 1.6 : .3);
    // legs
    ctx.fillStyle = '#2f332a';
    const legOff = Math.sin(this.walk) * (this.moving ? 6 : 0);
    roundedRect(ctx, -7 + legOff, -8, 13, 6, 3); ctx.fill();
    roundedRect(ctx, -7 - legOff, 2, 13, 6, 3); ctx.fill();
    ctx.fillStyle = '#1d1f1a';
    roundedRect(ctx, 2 + legOff, -8, 5, 6, 2); ctx.fill();
    roundedRect(ctx, 2 - legOff, 2, 5, 6, 2); ctx.fill();
    // backpack
    ctx.fillStyle = '#4a3c28'; roundedRect(ctx, -11, -7, 9, 14, 3); ctx.fill();
    ctx.fillStyle = '#5d4b32'; roundedRect(ctx, -10, -5, 4, 10, 2); ctx.fill();
    // torso
    ctx.fillStyle = this.hitFlash > 0 ? '#d8d2b8' : '#4a513c';
    roundedRect(ctx, -7, -9 + bob * .2, 17, 18, 6); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.07)';
    roundedRect(ctx, -5, -8 + bob * .2, 13, 6, 3); ctx.fill();
    // tactical vest strap
    ctx.fillStyle = '#31362a'; ctx.fillRect(-2, -9, 4, 18);
    ctx.fillStyle = '#b08a4c'; ctx.fillRect(1, -8, 2, 16);
    // arms + gun
    const kick = this.recoil * .8;
    ctx.fillStyle = '#3f4634';
    roundedRect(ctx, 2, -9, 10, 5, 2.5); ctx.fill();
    roundedRect(ctx, 2, 4, 10, 5, 2.5); ctx.fill();
    ctx.fillStyle = '#c49a6c';
    roundedRect(ctx, 10, -7, 5, 4, 2); ctx.fill();
    roundedRect(ctx, 10, 3, 5, 4, 2); ctx.fill();
    // weapon
    const w = this.weapon;
    const gunLen = w.id === 'shotgun' ? 28 : w.id === 'rifle' ? 31 : w.id === 'smg' ? 23 : 18;
    ctx.translate(-kick, 0);
    ctx.fillStyle = '#1b1d1a';
    roundedRect(ctx, 9, -2.6, gunLen, 5.2, 1.5); ctx.fill();
    ctx.fillStyle = '#2d302b';
    ctx.fillRect(12, -3.6, gunLen * .42, 1.7);
    ctx.fillStyle = '#3b3a2e';
    roundedRect(ctx, 10, 1, 7, 4.5, 1.5); ctx.fill();
    if (w.id === 'shotgun') { ctx.fillStyle = '#4b3622'; roundedRect(ctx, 6, -2, 8, 4, 2); ctx.fill(); }
    if (w.id === 'rifle') { ctx.fillStyle = '#1b1d1a'; roundedRect(ctx, 12, -5, 12, 2.5, 1); ctx.fill(); }
    ctx.fillStyle = '#0f110e'; ctx.fillRect(9 + gunLen - 2, -1.6, 4, 3.2);
    // head
    ctx.fillStyle = '#c49a6c';
    ctx.beginPath(); ctx.arc(2.5, -0.5, 6.6, 0, TAU); ctx.fill();
    // beanie
    ctx.fillStyle = '#3a4033';
    ctx.beginPath(); ctx.arc(2, -1.4, 6.4, Math.PI * .84, Math.PI * 2.12); ctx.fill();
    ctx.fillStyle = '#2b3026'; ctx.fillRect(-4.2, -2.4, 8, 2);
    // beard
    ctx.fillStyle = '#5c4a33'; ctx.beginPath(); ctx.arc(5.2, 1.4, 3.4, 0, TAU); ctx.fill();
    ctx.fillStyle = '#1b1b16'; ctx.beginPath(); ctx.arc(7.5, 0.4, 1, 0, TAU); ctx.fill();
    // collar / scarf
    ctx.fillStyle = '#a06a3c'; ctx.fillRect(1, -7, 4, 4);
    ctx.restore();
  }
}

export class Dog {
  constructor(name, key, x, y, variant) {
    this.name = name; this.key = key;
    this.x = x; this.y = y; this.r = 14;
    this.variant = variant; // lou | safi
    this.maxHp = variant === 'lou' ? 120 : 100;
    this.hp = this.maxHp;
    this.level = 1; this.xp = 0; this.xpNext = 65;
    this.dmg = variant === 'lou' ? 24 : 16;
    this.attackRate = variant === 'lou' ? .95 : .62;
    this.speed = variant === 'lou' ? 252 : 282;
    this.angle = 0; this.walk = 0; this.moving = false;
    this.state = 'follow';
    this.target = null;
    this.attackCd = rand(0, .4);
    this.bite = 0;
    this.downTimer = 0;
    this.hitFlash = 0;
    this.barkCd = rand(2, 6);
    this.slot = variant === 'lou' ? -1 : 1;
    this.stuck = 0;
    this.ring = 0;
  }

  update(dt, game) {
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.bite = Math.max(0, this.bite - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.barkCd = Math.max(0, this.barkCd - dt);
    this.ring = Math.max(0, this.ring - dt);
    if (this.state === 'downed') {
      this.downTimer -= dt;
      this.walk += dt * 2;
      if (game.player.hp > 0) {
        const d = dist(this.x, this.y, game.player.x, game.player.y);
        if (d > 36) World.moveCircle(this, (game.player.x - this.x) / d * 42 * dt, (game.player.y - this.y) / d * 42 * dt, this.r);
      }
      if (this.downTimer <= 0) this.revive(game, .35);
      return;
    }
    // find target
    let best = null, bd = 1e9;
    for (const z of game.zombies) {
      if (z.dead) continue;
      const d = dist2(this.x, this.y, z.x, z.y);
      if (d < bd && d < 420 * 420) { bd = d; best = z; }
    }
    this.target = best;
    let tx, ty, speed;

    if (best) {
      tx = best.x; ty = best.y;
      const d = Math.sqrt(bd);
      if (d < best.r + 27 && this.attackCd <= 0) {
        // bite
        this.attackCd = this.attackRate;
        this.bite = .22;
        const dmg = this.dmg * (1 + (this.level - 1) * .13);
        game.damageZombie(best, dmg, this, false);
        game.bloodBurst(best.x, best.y, 5, this.angle);
        Audio.bark();
        game.shake(2);
        this.x += Math.cos(this.angle) * 10;
        this.y += Math.sin(this.angle) * 10;
      }
      speed = this.speed * 1.12;
      // lunge around target
      if (d < 70) speed *= .9;
    } else {
      const p = game.player;
      const back = 62;
      const side = 44 * this.slot;
      const baseA = p.moving ? Math.atan2(p.y - (p.y - Math.sin(p.angle)), p.x - (p.x - Math.cos(p.angle))) : p.angle;
      const ca = Math.cos(p.angle + Math.PI * .5), sa = Math.sin(p.angle + Math.PI * .5);
      tx = p.x - Math.cos(p.angle) * back + ca * side;
      ty = p.y - Math.sin(p.angle) * back + sa * side;
      speed = this.speed;
      // keep away from player overlap
      const pd = dist(this.x, this.y, p.x, p.y);
      if (pd < 34) { tx = this.x - (p.x - this.x); ty = this.y - (p.y - this.y); }
    }

    // avoid other dog
    let sepX = 0, sepY = 0;
    for (const d of game.dogs) {
      if (d === this || d.state === 'downed') continue;
      const dd = dist(this.x, this.y, d.x, d.y);
      if (dd < 44 && dd > 0) { sepX += (this.x - d.x) / dd * (44 - dd); sepY += (this.y - d.y) / dd * (44 - dd); }
    }
    let dx = tx - this.x + sepX * 1.2, dy = ty - this.y + sepY * 1.2;
    const dl = Math.hypot(dx, dy);
    this.moving = dl > 12;
    if (this.moving) {
      dx /= dl; dy /= dl;
      const desired = Math.atan2(dy, dx);
      this.angle = lerpAngle(this.angle, desired, 1 - Math.exp(-12 * dt));
      const beforeX = this.x, beforeY = this.y;
      World.moveCircle(this, Math.cos(this.angle) * speed * dt, Math.sin(this.angle) * speed * dt, this.r);
      const moved = dist(beforeX, beforeY, this.x, this.y);
      if (moved < speed * dt * .25) {
        this.stuck += dt;
        if (this.stuck > 1.1) { this.stuck = 0; World.moveCircle(this, Math.cos(this.angle + Math.PI / 2) * speed * dt * 2, Math.sin(this.angle + Math.PI / 2) * speed * dt * 2, this.r); }
      } else this.stuck = 0;
      this.walk += dt * (9 + speed / 55);
    } else {
      this.angle = lerpAngle(this.angle, best ? Math.atan2(best.y - this.y, best.x - this.x) : game.player.angle, 1 - Math.exp(-6 * dt));
      this.walk += dt * 2;
    }
    if (best && this.barkCd <= 0) { this.barkCd = rand(6, 12); if (Math.random() < .5) Audio.bark(); }

    // too far from player: catch up teleport
    const far = dist(this.x, this.y, game.player.x, game.player.y);
    if (far > 1150) {
      const a = Math.random() * TAU;
      for (let i = 0; i < 12; i++) {
        const nx = game.player.x + Math.cos(a + i) * 70, ny = game.player.y + Math.sin(a + i) * 70;
        if (!World.isBlocked(nx, ny, this.r)) { this.x = nx; this.y = ny; break; }
      }
    }
  }

  takeDamage(n, game) {
    if (this.state === 'downed') return;
    this.hp -= n;
    this.hitFlash = .16;
    game.damageNumber(this.x, this.y - 22, `-${Math.round(n)}`, '#e8b27a');
    if (this.hp <= 0) {
      this.hp = 0;
      this.state = 'downed';
      this.downTimer = 24;
      this.target = null;
      Audio.growl();
      game.toast(`<b>${this.name}</b> ist verletzt! Halte E gedrückt.`, 'bad');
      game.shake(5);
    }
  }

  revive(game, hpPercent = .55) {
    this.state = 'follow';
    this.hp = Math.max(1, Math.round(this.maxHp * hpPercent));
    this.downTimer = 0;
    this.ring = .8;
    game.toast(`<b>${this.name}</b> ist wieder auf den Beinen!`, 'dog');
    game.ring(this.x, this.y, 55, 'rgba(168,197,108,');
    Audio.bark();
  }

  gainXp(n, game) {
    if (this.state === 'downed') return;
    this.xp += n;
    while (this.xp >= this.xpNext) {
      this.xp -= this.xpNext;
      this.level++;
      this.xpNext = Math.round(this.xpNext * 1.32);
      this.maxHp += 16;
      this.hp = Math.min(this.maxHp, this.hp + 24);
      this.dmg *= 1.12;
      this.speed *= 1.025;
      game.toast(`<b>${this.name}</b> erreicht Level ${this.level}`, 'dog');
      game.ring(this.x, this.y, 40, 'rgba(168,197,108,');
      Audio.levelup();
    }
  }

  draw(ctx, t) {
    const down = this.state === 'downed';
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.38)';
    ctx.beginPath(); ctx.ellipse(this.x + 3, this.y + 6, 20, 9, 0, 0, TAU); ctx.fill();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.angle);
    if (down) { ctx.rotate(Math.PI / 2); ctx.scale(.92, 1); ctx.globalAlpha = .8; }
    if (this.hitFlash > 0) ctx.globalAlpha = .6;
    const cream = this.variant === 'safi';
    const body = cream ? '#ddd6c2' : '#7b4a27';
    const dark = cream ? '#b3a98e' : '#55311a';
    const light = cream ? '#f0ead9' : '#9c6433';
    const bob = Math.sin(this.walk) * (this.moving ? 1.4 : .2);
    // tail
    ctx.save();
    ctx.translate(-16, 1);
    ctx.rotate(Math.sin(t * 4 + (this.slot)) * .3);
    ctx.strokeStyle = body; ctx.lineWidth = 5; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(-8, -5, -13, -2); ctx.stroke();
    ctx.restore();
    // legs
    ctx.fillStyle = dark;
    const lo = Math.sin(this.walk) * 5;
    const lo2 = Math.sin(this.walk + Math.PI) * 5;
    roundedRect(ctx, -9 + lo, -10, 7, 5, 2.5); ctx.fill();
    roundedRect(ctx, -9 + lo2, 5, 7, 5, 2.5); ctx.fill();
    roundedRect(ctx, 8 - lo2, -10, 7, 5, 2.5); ctx.fill();
    roundedRect(ctx, 8 - lo, 5, 7, 5, 2.5); ctx.fill();
    // body
    ctx.fillStyle = body;
    ctx.beginPath(); ctx.ellipse(-3, 0, 16, 9.5, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.ellipse(-8, 0, 8, 7.5, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = light;
    ctx.beginPath(); ctx.ellipse(-1, 2, 11, 5, 0, 0, TAU); ctx.fill();
    // neck / head
    ctx.fillStyle = body;
    ctx.beginPath(); ctx.ellipse(11, 0, 9, 8, 0, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(19, 0, 7, 5.5, 0, 0, TAU); ctx.fill();
    // snout
    ctx.fillStyle = cream ? '#cabfa4' : '#8a5a30';
    ctx.beginPath(); ctx.ellipse(24, 0, 5, 3.8, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#191813';
    ctx.beginPath(); ctx.arc(27.5, 0, 2.2, 0, TAU); ctx.fill();
    // ears
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.moveTo(8, -7); ctx.lineTo(5, -16); ctx.lineTo(14, -9); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(8, 7); ctx.lineTo(5, 16); ctx.lineTo(14, 9); ctx.closePath(); ctx.fill();
    // eye
    ctx.fillStyle = '#12110d';
    ctx.beginPath(); ctx.arc(17, -3.5, 1.6, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(17, 3.5, 1.6, 0, TAU); ctx.fill();
    // collar
    ctx.strokeStyle = this.variant === 'lou' ? '#b53a2c' : '#3b6f8f';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(10, 0, 8, -.9, .9); ctx.stroke();
    ctx.fillStyle = '#d8b45c';
    ctx.beginPath(); ctx.arc(10, 7, 2, 0, TAU); ctx.fill();
    // attack bite flash
    if (this.bite > 0) {
      ctx.fillStyle = 'rgba(255,240,210,.55)';
      ctx.beginPath(); ctx.arc(28, 0, 6, 0, TAU); ctx.fill();
    }
    ctx.restore();
    if (this.state === 'downed') {
      ctx.save();
      ctx.translate(this.x, this.y - 34);
      ctx.fillStyle = 'rgba(8,10,8,.78)';
      ctx.fillRect(-30, -7, 60, 13);
      ctx.fillStyle = '#d06a4e';
      ctx.font = 'bold 9px Bahnschrift, Arial';
      ctx.textAlign = 'center';
      ctx.fillText(`${this.name.toUpperCase()} · ${Math.ceil(this.downTimer)}s`, 0, 2.5);
      ctx.restore();
    }
  }
}

let zombieId = 1;
export class Zombie {
  constructor(x, y, type, level = 1, isBoss = false) {
    const def = ZOMBIE_TYPES[type];
    this.id = zombieId++;
    this.x = x; this.y = y; this.type = type;
    this.r = def.r;
    this.maxHp = Math.round(def.hp * (1 + (level - 1) * .16) * (isBoss ? 1.25 : 1));
    this.hp = this.maxHp;
    this.speed = def.speed * (1 + Math.min(.5, (level - 1) * .025)) * rand(.88, 1.12);
    this.dmg = def.dmg + level * 1.4;
    this.xp = def.xp; this.score = def.score;
    this.scale = def.scale;
    this.angle = rand(0, TAU);
    this.walk = rand(0, 6);
    this.attackCd = rand(.2, 1);
    this.windup = 0;
    this.stagger = 0;
    this.hitFlash = 0;
    this.dead = false;
    this.spawn = 1;
    this.target = null;
    this.isBoss = isBoss || type === 'boss';
    this.slamCd = 3;
    this.slamWind = 0;
    this.lunge = 0;
    this.phase = rand(0, TAU);
    this.seed = Math.random();
    this.shirt = def.shirt;
    this.skin = def.skin;
    if (this.isBoss) { this.slamCd = 4; this.shirt = '#2c3527'; }
  }

  update(dt, game) {
    if (this.dead) return;
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.spawn = Math.max(0, this.spawn - dt * 2);
    this.stagger = Math.max(0, this.stagger - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.slamCd = Math.max(0, this.slamCd - dt);
    this.bite = 0;

    // choose target
    let target = game.player;
    let bestD = dist2(this.x, this.y, target.x, target.y);
    for (const dog of game.dogs) {
      if (dog.state === 'downed') continue;
      const d = dist2(this.x, this.y, dog.x, dog.y) * 1.35;
      if (d < bestD) { bestD = d; target = dog; }
    }
    this.target = target;

    if (this.stagger > 0) { this.walk += dt * 2; return; }
    const dx = target.x - this.x, dy = target.y - this.y;
    const d = Math.hypot(dx, dy) || 1;
    const desired = Math.atan2(dy, dx);
    this.angle = lerpAngle(this.angle, desired, 1 - Math.exp(-(this.type === 'runner' ? 10 : 4) * dt));
    this.walk += dt * (this.type === 'runner' ? 14 : this.type === 'brute' ? 3.4 : 5.2);

    // boss slam
    if (this.isBoss) {
      if (this.slamWind > 0) {
        this.slamWind -= dt;
        if (this.slamWind <= 0) {
          game.bossSlam(this);
          this.slamCd = 5;
        }
        return;
      }
      if (this.slamCd <= 0 && d < 150) {
        this.slamWind = 1.0;
        this.slamCd = 6;
        game.telegraph(this.x, this.y, 155, 1.0);
        Audio.growl();
        return;
      }
    }

    const reach = this.r + target.r + 8;
    if (this.windup > 0) {
      this.windup -= dt;
      if (this.windup <= 0) {
        if (dist(this.x, this.y, target.x, target.y) < reach + 22) {
          if (target === game.player) target.takeDamage(this.dmg, game);
          else target.takeDamage(this.dmg, game);
          game.bloodBurst(target.x, target.y, 4, this.angle);
          this.attackCd = this.type === 'runner' ? .75 : 1.15;
        }
      }
      return;
    }
    if (d < reach && this.attackCd <= 0) {
      this.windup = this.type === 'runner' ? .22 : .38;
      this.lunge = .3;
      if (this.type === 'runner' && Math.random() < .5) Audio.growl();
      return;
    }
    // movement with separation
    let sx = 0, sy = 0;
    for (const z of game.zombies) {
      if (z === this || z.dead) continue;
      const dd = dist2(this.x, this.y, z.x, z.y);
      const sep = (this.r + z.r + 4) ** 2;
      if (dd < sep && dd > 0.01) {
        const dl = Math.sqrt(dd);
        sx += (this.x - z.x) / dl * (1 - dl / (this.r + z.r + 4));
        sy += (this.y - z.y) / dl * (1 - dl / (this.r + z.r + 4));
      }
    }
    let vx = Math.cos(this.angle) + sx * 1.6;
    let vy = Math.sin(this.angle) + sy * 1.6;
    if (this.lunge > 0) { this.lunge -= dt; vx *= 1.5; vy *= 1.5; }
    const vlen = Math.hypot(vx, vy) || 1;
    vx /= vlen; vy /= vlen;
    // obstacle avoidance
    const ahead = World.isBlocked(this.x + vx * (this.r + 16), this.y + vy * (this.r + 16), this.r * .8);
    if (ahead) {
      const side = this.seed > .5 ? 1 : -1;
      vx = vx * .35 - vy * side * .95;
      vy = vy * .35 + vx * side * .95;
    }
    const sp = this.speed * (this.isBoss ? (this.slamWind > 0 ? .2 : 1) : 1);
    const beforeX = this.x, beforeY = this.y;
    World.moveCircle(this, vx * sp * dt, vy * sp * dt, this.r);
    if (dist(beforeX, beforeY, this.x, this.y) < sp * dt * .2) {
      // slide fallback
      World.moveCircle(this, -vy * sp * dt * .8, vx * sp * dt * .8, this.r);
    }
  }

  takeDamage(n, game, crit, source) {
    if (this.dead) return;
    this.hp -= n;
    this.hitFlash = .12;
    if (this.type === 'brute' || this.isBoss) this.stagger = Math.max(this.stagger, .05);
    else if (Math.random() < .12) this.stagger = .18;
    if (this.hp <= 0) { this.hp = 0; game.killZombie(this, source || game.player); }
  }

  draw(ctx, t) {
    const s = this.scale;
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.4)';
    ctx.beginPath(); ctx.ellipse(this.x + 4 * s, this.y + 7 * s, 19 * s, 10 * s, 0, 0, TAU); ctx.fill();
    ctx.translate(this.x, this.y);
    if (this.spawn > 0) ctx.globalAlpha = 1 - this.spawn;
    ctx.rotate(this.angle);
    ctx.scale(s, s);
    const bob = Math.sin(this.walk) * 1.2;
    const flash = this.hitFlash > 0;
    // legs
    ctx.fillStyle = '#31332b';
    const lo = Math.sin(this.walk) * 5;
    roundedRect(ctx, -8 + lo, -7, 13, 5, 2); ctx.fill();
    roundedRect(ctx, -8 - lo, 2, 13, 5, 2); ctx.fill();
    // arms reaching forward
    ctx.strokeStyle = flash ? '#d8d6c2' : this.skin;
    ctx.lineWidth = 4.5; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(2, -7); ctx.lineTo(17, -10 + Math.sin(this.walk + 1) * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(2, 7); ctx.lineTo(17, 10 + Math.sin(this.walk) * 2); ctx.stroke();
    // hands
    ctx.fillStyle = this.skin;
    ctx.beginPath(); ctx.arc(18, -10 + Math.sin(this.walk + 1) * 2, 2.6, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(18, 10 + Math.sin(this.walk) * 2, 2.6, 0, TAU); ctx.fill();
    // torso
    ctx.fillStyle = flash ? '#e6e1c8' : this.shirt;
    roundedRect(ctx, -9, -9 + bob * .2, 18, 18, 5); ctx.fill();
    // torn shirt
    ctx.fillStyle = 'rgba(15,16,12,.35)';
    ctx.beginPath(); ctx.moveTo(-4, -9); ctx.lineTo(1, -2); ctx.lineTo(-2, 8); ctx.lineTo(-8, 9); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(90,25,18,.55)';
    ctx.beginPath(); ctx.ellipse(3, 1, 4.5, 3, .4, 0, TAU); ctx.fill();
    // head
    ctx.fillStyle = flash ? '#f0ead2' : this.skin;
    ctx.beginPath(); ctx.arc(2, 0, 7, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(30,30,22,.4)';
    ctx.beginPath(); ctx.arc(-.5, -1, 5.4, 0, TAU); ctx.fill();
    // eyes glow
    ctx.fillStyle = this.isBoss ? '#ff8a3c' : '#d6d38a';
    ctx.beginPath(); ctx.arc(5, -3, 1.5, 0, TAU); ctx.arc(5, 3, 1.5, 0, TAU); ctx.fill();
    // jaw
    ctx.fillStyle = 'rgba(90,30,25,.7)';
    ctx.beginPath(); ctx.ellipse(6.5, 0, 2.6, 2, 0, 0, TAU); ctx.fill();
    // shirt details
    ctx.strokeStyle = 'rgba(0,0,0,.22)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-6, -6); ctx.lineTo(4, -6); ctx.moveTo(-6, 6); ctx.lineTo(3, 6); ctx.stroke();
    if (this.isBoss) {
      ctx.fillStyle = '#3a3f2e';
      ctx.beginPath(); ctx.arc(0, 0, 12, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#565a42'; ctx.lineWidth = 3;
      for (let i = 0; i < 6; i++) {
        const a = i / 6 * TAU;
        ctx.beginPath(); ctx.moveTo(Math.cos(a) * 11, Math.sin(a) * 11); ctx.lineTo(Math.cos(a) * 19, Math.sin(a) * 19); ctx.stroke();
      }
    }
    ctx.restore();

    // health bar
    if (this.hp < this.maxHp || this.isBoss) {
      const w = this.isBoss ? 90 : 32 * this.scale;
      const yy = this.y - (28 * this.scale) - 8;
      if (this.isBoss) return;
      ctx.fillStyle = 'rgba(5,7,5,.7)'; ctx.fillRect(this.x - w / 2 - 1, yy - 1, w + 2, 5);
      ctx.fillStyle = this.type === 'brute' ? '#c04a32' : '#b8723f';
      ctx.fillRect(this.x - w / 2, yy, w * (this.hp / this.maxHp), 3);
    }
  }
}

export class Bullet {
  constructor(x, y, vx, vy, dmg, pierce, crit, kind) {
    this.x = x; this.y = y; this.vx = vx; this.vy = vy;
    this.dmg = dmg; this.pierce = pierce; this.crit = crit;
    this.kind = kind; this.life = .7; this.dead = false;
    this.hits = new Set();
    this.px = x; this.py = y;
  }
  update(dt, game) {
    this.px = this.x; this.py = this.y;
    this.x += this.vx * dt; this.y += this.vy * dt;
    this.life -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    if (World.isBlocked(this.x, this.y, 2)) {
      this.dead = true;
      game.sparks(this.x, this.y, 3, '#d8c890');
      return;
    }
    for (const z of game.zombies) {
      if (z.dead || this.hits.has(z.id)) continue;
      if (dist2(this.x, this.y, z.x, z.y) < (z.r + 5) ** 2) {
        this.hits.add(z.id);
        game.damageZombie(z, this.dmg, game.player, this.crit);
        game.bloodBurst(this.x, this.y, this.crit ? 9 : 4, Math.atan2(this.vy, this.vx));
        if (this.crit) { Audio.crit(); game.floatingText(this.x, this.y - 12, 'KRITISCH', '#ffd27a'); }
        if (this.pierce > 0) { this.pierce--; } else { this.dead = true; }
        break;
      }
    }
  }
}

export class Pickup {
  constructor(x, y, type) {
    this.x = x; this.y = y; this.type = type; this.t = Math.random() * 6; this.dead = false; this.life = 45; this.r = 18;
  }
  update(dt, game) {
    this.t += dt; this.life -= dt;
    if (this.life <= 0) this.dead = true;
    if (game.player.hp > 0 && dist2(this.x, this.y, game.player.x, game.player.y) < 34 * 34) {
      this.collect(game);
    }
  }
  collect(game) {
    if (this.dead) return;
    this.dead = true;
    const p = game.player;
    let label = '';
    switch (this.type) {
      case 'medkit':
        p.heal(38);
        game.dogs.forEach(d => { if (d.state !== 'downed') d.heal(20); });
        label = '+38 LEBEN'; break;
      case 'ammo':
        for (const k of Object.keys(p.weapons)) {
          const w = p.weapons[k];
          if (w.reserve !== Infinity) w.reserve = Math.min(WEAPONS[k].reserve * 2, w.reserve + Math.ceil(WEAPONS[k].reserve * .45));
        }
        label = 'MUNITION AUFGEFÜLLT'; break;
      case 'adrenaline':
        p.damageBuff = 12; label = 'ADRENALIN · DMG ×2'; break;
      case 'speed':
        p.speedBuff = 12; label = 'HETZJAGD · TEMPO'; break;
      case 'shield':
        p.shield = Math.max(p.shield, 60); label = '+60 SCHILD'; break;
      case 'treat':
        game.dogs.forEach(d => { if (d.state === 'downed') d.revive(game, .6); else d.hp = Math.min(d.maxHp, d.hp + 55); });
        label = 'LECKERLI · HUNDE GEHEILT'; break;
    }
    game.floatingText(this.x, this.y - 10, label, '#ffd27a');
    game.toast(label.replace('·', '<b>·</b>'));
    Audio.powerup();
    game.ring(this.x, this.y, 30, this.type === 'medkit' ? 'rgba(210,90,80,' : 'rgba(255,210,122,');
  }
  draw(ctx, t) {
    const bob = Math.sin(this.t * 2.4) * 3;
    ctx.save();
    ctx.translate(this.x, this.y + bob);
    const colors = {
      medkit: ['#c4473a', '#ff8c78'], ammo: ['#b6903f', '#ffd27a'], adrenaline: ['#c0772e', '#ffbe62'],
      speed: ['#3f8b8a', '#7ee0d8'], shield: ['#3e6f9c', '#8dcdff'], treat: ['#7d9a52', '#c6e58a'],
    }[this.type] || ['#ccc', '#fff'];
    ctx.fillStyle = `rgba(${this.type === 'medkit' ? '196,71,58' : '227,161,60'},.12)`;
    ctx.beginPath(); ctx.arc(0, 0, 24 + Math.sin(this.t * 2) * 2, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(0,0,0,.4)';
    ctx.beginPath(); ctx.ellipse(2, 12, 12, 5, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = colors[0];
    roundedRect(ctx, -9, -9, 18, 18, 4); ctx.fill();
    ctx.strokeStyle = colors[1]; ctx.lineWidth = 1.5;
    roundedRect(ctx, -9, -9, 18, 18, 4); ctx.stroke();
    ctx.fillStyle = colors[1];
    if (this.type === 'medkit') {
      ctx.fillRect(-2, -6, 4, 12); ctx.fillRect(-6, -2, 12, 4);
    } else if (this.type === 'ammo') {
      ctx.fillRect(-5, -6, 3, 11); ctx.fillRect(-1, -6, 3, 11); ctx.fillRect(3, -6, 3, 11);
    } else if (this.type === 'adrenaline') {
      ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 1); ctx.lineTo(0, 1); ctx.lineTo(3, 8); ctx.lineTo(-5, -1); ctx.lineTo(0, -1); ctx.closePath(); ctx.fill();
    } else if (this.type === 'speed') {
      ctx.beginPath(); ctx.moveTo(-6, -6); ctx.lineTo(2, 0); ctx.lineTo(-6, 6); ctx.lineTo(-2, 0); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(8, 0); ctx.lineTo(0, 6); ctx.lineTo(4, 0); ctx.closePath(); ctx.fill();
    } else if (this.type === 'shield') {
      ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(7, -4); ctx.lineTo(5, 5); ctx.lineTo(0, 8); ctx.lineTo(-5, 5); ctx.lineTo(-7, -4); ctx.closePath(); ctx.fill();
    } else {
      ctx.beginPath(); ctx.arc(-2, -1, 4, 0, TAU); ctx.fill();
      ctx.fillRect(-10, 1, 16, 4);
    }
    ctx.restore();
  }
  heal() { }
}

// add Dog.heal
Dog.prototype.heal = function (n) { if (this.state !== 'downed') this.hp = Math.min(this.maxHp, this.hp + n); };

import { formatTime, clamp } from './util.js';
import { World, BUILDINGS, MAP, CAMPFIRE, POND } from './world.js';
import { WEAPONS } from './entities.js';
import { Input } from './input.js';
import { Audio } from './audio.js';

const $ = id => document.getElementById(id);

export const UI = {
  game: null,
  screen: 'title',
  controlsReturn: 'title',
  cards: [],
  cardHandler: null,
  bannerTimer: 0,
  minimapBase: null,
  last: {},

  init(game) {
    this.game = game;
    this.refs = {
      hud: $('hud'), title: $('title-screen'), controls: $('controls-screen'),
      levelup: $('levelup-screen'), pause: $('pause-screen'), over: $('gameover-screen'),
      touch: $('touch-ui'), loading: $('loading'),
      banner: $('wave-banner'), bannerSmall: $('banner-small'), bannerBig: $('banner-big'),
      prompt: $('prompt'), promptText: $('prompt-text'), toasts: $('toasts'),
      rickLevel: $('rick-level'), rickHpFill: $('rick-hp-fill'), rickHpText: $('rick-hp-text'),
      rickXpFill: $('rick-xp-fill'), rickArmor: $('rick-armor'),
      buffDmg: $('buff-dmg'), buffSpd: $('buff-spd'),
      louLevel: $('lou-level'), louHpFill: $('lou-hp-fill'), louState: $('lou-state'),
      safiLevel: $('safi-level'), safiHpFill: $('safi-hp-fill'), safiState: $('safi-state'),
      louCard: $('dog-card-lou'), safiCard: $('dog-card-safi'),
      waveNum: $('wave-num'), waveEnemies: $('wave-enemies'), waveTimer: $('wave-timer'),
      score: $('score'), weaponName: $('weapon-name'), ammoMag: $('ammo-mag'), ammoReserve: $('ammo-reserve'),
      reloadBar: $('reload-bar'), reloadFill: $('reload-fill'), dashFill: $('dash-fill'),
      bossBar: $('boss-bar'), bossFill: $('boss-fill'),
      bestWave: $('best-wave'), bestScore: $('best-score'),
      goWave: $('go-wave'), goKills: $('go-kills'), goScore: $('go-score'), goTime: $('go-time'), goRecord: $('go-record'),
      cards: $('cards'), levelupLevel: $('levelup-level'),
      pauseWave: $('pause-wave'), pauseScore: $('pause-score'), pauseKills: $('pause-kills'), pauseTime: $('pause-time'),
      minimap: $('minimap'), touchUI: $('touch-ui'),
    };
    this.bindControls();
    this.buildMinimapBase();
    const best = this.loadBest();
    this.refs.bestWave.textContent = best.wave;
    this.refs.bestScore.textContent = best.score.toLocaleString('de-DE');
    this.soundLabel();
  },

  bindControls() {
    const g = this.game;
    $('btn-play').addEventListener('click', () => g.startRun());
    $('btn-controls').addEventListener('click', () => { this.controlsReturn = 'title'; this.show('controls'); });
    $('btn-controls-back').addEventListener('click', () => this.show(this.controlsReturn));
    $('btn-sound').addEventListener('click', () => this.toggleSound());
    $('btn-pause-mute').addEventListener('click', () => this.toggleSound());
    $('btn-resume').addEventListener('click', () => g.resume());
    $('btn-pause-controls').addEventListener('click', () => { this.controlsReturn = 'pause'; this.show('controls'); });
    $('btn-pause-restart').addEventListener('click', () => g.startRun());
    $('btn-restart').addEventListener('click', () => g.startRun());
    $('btn-menu').addEventListener('click', () => g.toMenu());
    $('btn-sound') && $('btn-sound').addEventListener('click', () => Audio.resume());

    // touch sticks
    const stick = (el, thumb, cb) => {
      let active = null, id = null;
      const update = e => {
        const r = el.getBoundingClientRect();
        const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        let dx = e.clientX - cx, dy = e.clientY - cy;
        const max = r.width * .38;
        const len = Math.hypot(dx, dy);
        if (len > max) { dx = dx / len * max; dy = dy / len * max; }
        thumb.style.transform = `translate(${dx}px, ${dy}px)`;
        cb(dx / max, dy / max, true);
      };
      el.addEventListener('pointerdown', e => {
        e.preventDefault(); active = el; id = e.pointerId;
        el.setPointerCapture(id); update(e);
      });
      el.addEventListener('pointermove', e => { if (active && e.pointerId === id) update(e); });
      const end = e => {
        if (!active || e.pointerId !== id) return;
        active = null; id = null;
        thumb.style.transform = 'translate(0px,0px)';
        cb(0, 0, false);
      };
      el.addEventListener('pointerup', end);
      el.addEventListener('pointercancel', end);
    };
    const moveKnob = document.querySelector('#stick-move .stick-knob');
    const aimKnob = document.querySelector('#stick-aim .stick-knob');
    stick($('stick-move'), moveKnob, (x, y, on) => {
      Input.touch.moveX = on ? x : 0;
      Input.touch.moveY = on ? y : 0;
    });
    stick($('stick-aim'), aimKnob, (x, y, on) => {
      Input.touch.aimX = on ? x : 0;
      Input.touch.aimY = on ? y : 0;
      Input.touch.aimActive = on && Math.hypot(x, y) > .2;
      Input.touch.fire = on && Math.hypot(x, y) > .2;
    });
    const dash = $('touch-dash'), reload = $('touch-reload'), use = $('touch-use');
    dash.addEventListener('pointerdown', e => { e.preventDefault(); Input.touch.dash = true; Audio.resume(); });
    reload.addEventListener('pointerdown', e => { e.preventDefault(); Input.touch.reload = true; });
    use.addEventListener('pointerdown', e => { e.preventDefault(); Input.touch.use = true; });
  },

  toggleSound() {
    Audio.init();
    Audio.setMuted(!Audio.muted);
    this.soundLabel();
  },
  soundLabel() {
    const label = Audio.muted ? 'SOUND: AUS' : 'SOUND: AN';
    if ($('btn-sound')) $('btn-sound').textContent = label;
    if ($('btn-pause-mute')) $('btn-pause-mute').textContent = label;
  },

  show(name) {
    this.screen = name;
    const map = { title: 'title', controls: 'controls', levelup: 'levelup', pause: 'pause', gameover: 'over', none: null };
    for (const key of ['title', 'controls', 'levelup', 'pause', 'over']) {
      if (this.refs[key]) this.refs[key].classList.add('hidden');
    }
    const key = map[name];
    if (key && this.refs[key]) this.refs[key].classList.remove('hidden');
    const inGame = ['none', 'levelup', 'pause'].includes(name);
    this.refs.hud.classList.toggle('hidden', !inGame);
    this.refs.touchUI.classList.toggle('hidden', !(inGame && Input.isTouch));
    document.body.classList.toggle('in-game', inGame);
  },

  hideLoading() { this.refs.loading.classList.add('hidden'); },

  update(dt, game) {
    if (!this.refs) return;
    this.updateBanner(dt);
    if (!['none', 'levelup', 'pause'].includes(this.screen)) return;
    const p = game.player;
    if (!p) return;
    const r = this.refs;
    r.rickLevel.textContent = 'LV ' + p.level;
    r.rickHpFill.style.width = clamp(p.hp / p.maxHp * 100, 0, 100) + '%';
    r.rickHpText.textContent = `${Math.ceil(p.hp)} / ${p.maxHp}`;
    r.rickHpFill.parentElement.classList.toggle('low', p.hp / p.maxHp < .3);
    r.rickXpFill.style.width = clamp(p.xp / p.xpNext * 100, 0, 100) + '%';
    r.rickArmor.textContent = '◈ ' + Math.round(p.shield);
    r.rickArmor.classList.toggle('hidden', p.shield <= 0);
    r.buffDmg.classList.toggle('hidden', p.damageBuff <= 0);
    r.buffSpd.classList.toggle('hidden', p.speedBuff <= 0);

    const dogInfo = (dog, levelEl, fillEl, stateEl, card) => {
      levelEl.textContent = 'LV ' + dog.level;
      fillEl.style.width = clamp(dog.hp / dog.maxHp * 100, 0, 100) + '%';
      const downed = dog.state === 'downed';
      stateEl.textContent = downed ? `VERLETZT ${Math.ceil(dog.downTimer)}s` : dog.target ? 'KÄMPFT' : 'WACH';
      stateEl.classList.toggle('down', downed);
      card.classList.toggle('downed', downed);
    };
    dogInfo(game.dogs[0], r.louLevel, r.louHpFill, r.louState, r.louCard);
    dogInfo(game.dogs[1], r.safiLevel, r.safiHpFill, r.safiState, r.safiCard);

    const w = p.weapon;
    r.weaponName.textContent = w.name;
    r.ammoMag.textContent = w.mag;
    r.ammoReserve.textContent = w.reserve === Infinity ? '/ ∞' : '/ ' + w.reserve;
    r.ammoMag.parentElement.classList.toggle('empty', w.mag === 0);
    r.reloadBar.classList.toggle('hidden', p.reloading <= 0);
    if (p.reloading > 0) r.reloadFill.style.width = (100 - p.reloading / (p.reloadDuration || 1) * 100) + '%';
    const slots = ['pistol', 'shotgun', 'smg', 'rifle'];
    document.querySelectorAll('.slot').forEach((el, i) => {
      el.classList.toggle('active', slots[i] === p.current);
      el.classList.toggle('locked', !p.weapons[slots[i]]);
      if (p.weapons[slots[i]]) el.textContent = `${i + 1} · ${WEAPONS[slots[i]].short}`;
    });
    r.dashFill.style.transform = `scaleY(${clamp(p.dashCd / (p.dashCdMax * p.upgrades.dashCd), 0, 1)})`;
    if (p.dashCd <= 0) r.dashFill.style.background = 'rgba(227,161,60,.55)';
    else r.dashFill.style.background = 'rgba(227,161,60,.18)';

    // wave / score
    const remaining = game.zombies.length + game.pendingSpawns;
    r.waveNum.textContent = game.wave;
    r.waveEnemies.textContent = `${remaining} GEGNER`;
    r.waveTimer.textContent = formatTime(game.runTime);
    r.score.textContent = game.score.toLocaleString('de-DE');
    const boss = game.zombies.find(z => z.isBoss && !z.dead);
    r.bossBar.classList.toggle('hidden', !boss);
    if (boss) r.bossFill.style.width = clamp(boss.hp / boss.maxHp * 100, 0, 100) + '%';

    this.drawMinimap(game);
  },

  banner(small, big, duration = 2.4) {
    const r = this.refs;
    r.bannerSmall.textContent = small;
    r.bannerBig.textContent = big;
    r.banner.classList.add('show');
    this.bannerTimer = duration;
  },
  updateBanner(dt) {
    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt;
      if (this.bannerTimer <= 0) this.refs.banner.classList.remove('show');
    }
  },

  toast(text, cls = '') {
    const el = document.createElement('div');
    el.className = 'toast ' + cls;
    el.innerHTML = text;
    this.refs.toasts.appendChild(el);
    setTimeout(() => el.remove(), 3200);
    const kids = this.refs.toasts.children;
    while (kids.length > 5) kids[0].remove();
  },

  prompt(text) {
    if (this.last.prompt === text) return;
    this.last.prompt = text;
    const el = this.refs.prompt;
    if (!text) { el.classList.add('hidden'); return; }
    el.classList.remove('hidden');
    this.refs.promptText.textContent = text;
  },

  showLevelUp(level, cards, onPick) {
    this.refs.levelupLevel.textContent = level;
    this.cards = cards;
    this.cardHandler = onPick;
    const wrap = this.refs.cards;
    wrap.innerHTML = '';
    cards.forEach((card, i) => {
      const el = document.createElement('button');
      el.className = 'card';
      el.style.setProperty('--accent', card.accent || '#e3a13c');
      el.innerHTML = `<div class="card-cat">${card.cat}</div>
        <div class="card-icon">${card.icon}</div>
        <h3>${card.title}</h3>
        <p>${card.desc}</p>
        <div class="card-foot"><span class="card-key"><kbd>${i + 1}</kbd> WÄHLEN</span><span class="card-stat">${card.stat || ''}</span></div>`;
      el.addEventListener('click', () => this.pickCard(i));
      wrap.appendChild(el);
    });
    this.show('levelup');
  },
  pickCard(i) {
    if (!this.cardHandler || !this.cards[i]) return;
    const cb = this.cardHandler;
    this.cardHandler = null;
    cb(i);
  },
  hideLevelUp() { this.show('none'); },

  updatePause(game) {
    this.refs.pauseWave.textContent = game.wave;
    this.refs.pauseScore.textContent = game.score.toLocaleString('de-DE');
    this.refs.pauseKills.textContent = game.kills;
    this.refs.pauseTime.textContent = formatTime(game.runTime);
    this.soundLabel();
  },

  updateGameOver(game, isRecord) {
    this.refs.goWave.textContent = game.wave;
    this.refs.goKills.textContent = game.kills;
    this.refs.goScore.textContent = game.score.toLocaleString('de-DE');
    this.refs.goTime.textContent = formatTime(game.runTime);
    this.refs.goRecord.classList.toggle('hidden', !isRecord);
  },

  loadBest() {
    try { return JSON.parse(localStorage.getItem('garath-best')) || { wave: 1, score: 0 }; }
    catch { return { wave: 1, score: 0 }; }
  },
  saveBest(wave, score) {
    const prev = this.loadBest();
    const next = { wave: Math.max(prev.wave, wave), score: Math.max(prev.score, score) };
    try { localStorage.setItem('garath-best', JSON.stringify(next)); } catch { }
    this.refs.bestWave.textContent = next.wave;
    this.refs.bestScore.textContent = next.score.toLocaleString('de-DE');
    return score > prev.score;
  },

  buildMinimapBase() {
    const c = document.createElement('canvas');
    c.width = 240; c.height = 190;
    const x = c.getContext('2d');
    const s = 240 / MAP.w;
    const oy = (190 - MAP.h * s) / 2;
    x.fillStyle = '#101710'; x.fillRect(0, 0, 240, 190);
    x.save(); x.translate(0, oy); x.scale(s, s);
    // forest base
    x.fillStyle = '#1d2819'; x.fillRect(0, 0, MAP.w, MAP.h);
    // road
    x.fillStyle = '#3a3d36'; x.fillRect(0, 250, MAP.w, 190);
    // paths
    x.strokeStyle = '#4a402c'; x.lineWidth = 110; x.lineCap = 'round'; x.lineJoin = 'round';
    for (const path of [
      [[1750, 430], [1750, 720], [1715, 1030], [1750, 1420]],
      [[1750, 1420], [1470, 1385], [1230, 1295], [1000, 1195]],
      [[1750, 1420], [2050, 1475], [2350, 1512], [2450, 1512]],
      [[1750, 1420], [1650, 1690], [1360, 1870], [1060, 1960]],
    ]) {
      x.beginPath(); x.moveTo(path[0][0], path[0][1]);
      for (const pt of path.slice(1)) x.lineTo(pt[0], pt[1]);
      x.stroke();
    }
    // pond
    x.fillStyle = '#1c3436'; x.beginPath(); x.ellipse(POND.x, POND.y, POND.rx, POND.ry, 0, 0, Math.PI * 2); x.fill();
    // buildings
    for (const b of BUILDINGS) {
      x.fillStyle = '#59492e'; x.fillRect(b.x, b.y, b.w, b.h);
      x.strokeStyle = 'rgba(227,161,60,.55)'; x.lineWidth = 12; x.strokeRect(b.x, b.y, b.w, b.h);
    }
    // trees hint
    x.fillStyle = 'rgba(60,86,48,.5)';
    for (const t of World.trees) { x.beginPath(); x.arc(t.x, t.y, t.r * .55, 0, Math.PI * 2); x.fill(); }
    // campfire
    x.fillStyle = '#e8973c'; x.beginPath(); x.arc(CAMPFIRE.x, CAMPFIRE.y, 45, 0, Math.PI * 2); x.fill();
    x.restore();
    this.minimapBase = c;
    this.minimapScale = s;
    this.minimapOffset = oy;
  },

  drawMinimap(game) {
    const c = this.refs.minimap;
    if (!c) return;
    const x = c.getContext('2d');
    x.clearRect(0, 0, 240, 190);
    x.drawImage(this.minimapBase, 0, 0);
    const s = this.minimapScale, oy = this.minimapOffset;
    const px = game.player.x * s, py = game.player.y * s + oy;
    // viewport
    x.strokeStyle = 'rgba(222,217,199,.12)'; x.lineWidth = 1;
    const vw = game.vw / game.cam.zoom * s, vh = game.vh / game.cam.zoom * s;
    x.strokeRect(px - vw / 2, py - vh / 2, vw, vh);
    // pickups
    x.fillStyle = '#ffd27a';
    for (const pk of game.pickups) { x.beginPath(); x.arc(pk.x * s, pk.y * s + oy, 1.8, 0, Math.PI * 2); x.fill(); }
    // zombies
    for (const z of game.zombies) {
      const d = Math.hypot(z.x - game.player.x, z.y - game.player.y);
      x.fillStyle = z.isBoss ? '#ff7a4a' : d < 700 ? 'rgba(220,80,60,.9)' : 'rgba(220,80,60,.35)';
      x.beginPath(); x.arc(z.x * s, z.y * s + oy, z.isBoss ? 3.4 : 1.9, 0, Math.PI * 2); x.fill();
    }
    // dogs
    for (const d of game.dogs) {
      x.fillStyle = d.state === 'downed' ? '#a05a44' : d.variant === 'lou' ? '#b98853' : '#eee7d4';
      x.beginPath(); x.arc(d.x * s, d.y * s + oy, 2.3, 0, Math.PI * 2); x.fill();
    }
    // player arrow
    x.save(); x.translate(px, py); x.rotate(game.player.angle + Math.PI / 2);
    x.fillStyle = '#ffe0a0';
    x.beginPath(); x.moveTo(0, -5); x.lineTo(3.6, 4); x.lineTo(0, 2); x.lineTo(-3.6, 4); x.closePath(); x.fill();
    x.restore();
    // boss marker
    for (const z of game.zombies) if (z.isBoss) {
      x.strokeStyle = 'rgba(255,110,70,.7)'; x.lineWidth = 1.5;
      x.beginPath(); x.arc(z.x * s, z.y * s + oy, 6, 0, Math.PI * 2); x.stroke();
    }
  },
};

import { TAU, clamp, damp, dist, dist2, lerp, rand, randInt, chance, choice, shuffle } from './util.js';
import { World, MAP, CAMPFIRE, PLAYER_START, BUILDINGS } from './world.js';
import { Player, Dog, Zombie, Bullet, Pickup, WEAPONS } from './entities.js';
import { Input } from './input.js';
import { Audio } from './audio.js';
import { UI } from './ui.js';

const TAU2 = Math.PI * 2;

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.vw = window.innerWidth;
    this.vh = window.innerHeight;
    this.zoom = 1;
    this.cam = { x: CAMPFIRE.x, y: CAMPFIRE.y, zoom: 1, shake: 0 };
    this.time = 0;
    this.runTime = 0;
    this.state = 'loading';
    this.paused = false;
    this.score = 0;
    this.kills = 0;
    this.wave = 1;
    this.pendingSpawns = 0;
    this.spawnTimer = 0;
    this.waveActive = false;
    this.intermission = 0;
    this.waveQueue = 0;
    this.pendingLevelUps = 0;
    this.leveling = false;
    this.aimWorld = { x: 0, y: 0 };
    this.scrollDelta = 0;
    this.hurtFlash = 0;
    this.supplyTimer = 40;
    this.bullets = [];
    this.zombies = [];
    this.pickups = [];
    this.particles = [];
    this.floatingTexts = [];
    this.afterimages = [];
    this.telegraphs = [];
    this.shockwaves = [];
    this.crates = [];
    this.decals = [];
    this.menuAngle = 0;
    this.player = null;
    this.dogs = [];
    this.lightCanvas = document.createElement('canvas');
    this.lightCtx = this.lightCanvas.getContext('2d');
    this.lightScale = .5;
    this.boundLoop = this.loop.bind(this);
    this.fog = Array.from({ length: 7 }, () => ({ x: rand(0, 2000), y: rand(0, 1400), r: rand(260, 620), s: rand(3, 10), a: rand(.02, .05) }));
    this.fireflies = Array.from({ length: 34 }, () => ({ x: rand(0, 1600), y: rand(0, 1000), p: rand(0, TAU), s: rand(.2, .8) }));
    this.fpsSmoothed = 60;
  }

  init() {
    this.resize();
    window.addEventListener('resize', () => this.resize());
    this.canvas.addEventListener('wheel', e => { this.scrollDelta = Math.sign(e.deltaY); e.preventDefault(); }, { passive: false });
    Input.init(this.canvas);
    World.init();
    UI.init(this);
    this.setupMenuScene();
    this.state = 'title';
    UI.show('title');
    UI.hideLoading();
    requestAnimationFrame(this.boundLoop);
  }

  resize() {
    this.vw = window.innerWidth;
    this.vh = window.innerHeight;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.vw * this.dpr);
    this.canvas.height = Math.round(this.vh * this.dpr);
    this.zoom = clamp(Math.max(this.vw / 1250, this.vh / 1250), 0.52, 1.32);
    this.cam.zoom = this.zoom;
    this.lightCanvas.width = Math.round(this.vw * this.lightScale);
    this.lightCanvas.height = Math.round(this.vh * this.lightScale);
    if (!Input.mouse.x) { Input.mouse.x = this.vw / 2; Input.mouse.y = this.vh / 2; }
  }

  setupMenuScene() {
    this.player = new Player(PLAYER_START.x, PLAYER_START.y);
    this.player.angle = -0.4;
    this.dogs = [
      new Dog('Lou', 'lou', PLAYER_START.x - 58, PLAYER_START.y + 42, 'lou'),
      new Dog('Safi', 'safi', PLAYER_START.x + 46, PLAYER_START.y + 52, 'safi'),
    ];
    this.dogs[0].angle = -0.2; this.dogs[1].angle = 0.2;
    this.menuZombies = [];
    for (const [x, y, a] of [[2180, 1610, 3.4], [1320, 1240, .6], [2050, 1280, 2.8]]) {
      const z = new Zombie(x, y, 'walker', 1); z.angle = a; z.spawn = 0; z.walk = rand(0, 6);
      this.menuZombies.push(z);
    }
    this.zombies = this.menuZombies;
    this.bullets = []; this.pickups = []; this.particles = [];
  }

  startRun() {
    Audio.init();
    Audio.resume();
    this.state = 'playing';
    this.runTime = 0;
    this.score = 0;
    this.kills = 0;
    this.wave = 1;
    this.pendingSpawns = 0;
    this.spawnTimer = 0;
    this.waveActive = false;
    this.intermission = .45;
    this.pendingLevelUps = 0;
    this.leveling = false;
    this.bullets = [];
    this.zombies = [];
    this.pickups = [];
    this.particles = [];
    this.floatingTexts = [];
    this.afterimages = [];
    this.telegraphs = [];
    this.shockwaves = [];
    this.decals = [];
    this.supplyTimer = 42;
    this.hurtFlash = 0;
    this.menuZombies = [];
    this.player = new Player(PLAYER_START.x, PLAYER_START.y);
    this.player.angle = -0.2;
    this.dogs = [
      new Dog('Lou', 'lou', PLAYER_START.x - 55, PLAYER_START.y + 38, 'lou'),
      new Dog('Safi', 'safi', PLAYER_START.x + 48, PLAYER_START.y + 45, 'safi'),
    ];
    this.crates = [
      { x: 612, y: 1022, type: 'weapon', weapon: 'shotgun', label: 'FORSTFLINTE', opened: false },
      { x: 3152, y: 1862, type: 'weapon', weapon: 'smg', label: 'MP GARATH', opened: false },
      { x: 2168, y: 655, type: 'weapon', weapon: 'rifle', label: 'JAGDGEWEHR', opened: false },
      { x: 1945, y: 1490, type: 'supply', label: 'VORRÄTE', opened: false },
    ];
    this.cam.x = this.player.x; this.cam.y = this.player.y;
    this.cam.shake = 0;
    UI.show('none');
    UI.banner('GARATHER WALD · 22:47', 'ÜBERLEBE DIE NACHT', 3.2);
    UI.toast('Halte <b>E</b> gedrückt, um Lou und Safi wiederzubeleben.', 'dog');
    this.addFireBurst(this.player.x, this.player.y, 8);
    this.startWave(1);
  }

  toMenu() {
    this.state = 'title';
    Audio.resume();
    this.setupMenuScene();
    UI.show('title');
  }

  startWave(n) {
    this.wave = n;
    this.waveActive = true;
    this.pendingSpawns = 6 + Math.round(n * 3.4);
    this.spawnTimer = 0;
    this.intermission = 0;
    this.waveQueue = this.pendingSpawns;
    const boss = n % 5 === 0;
    UI.banner(`WELLE ${n}`, boss ? 'DER KOLOSS ERWACHT' : n === 1 ? 'DIE HERDE KOMMT' : 'SIE RIECHEN EUCH', 2.6);
    Audio.wave();
    if (boss) {
      this.pendingSpawns += 0;
      setTimeout(() => this.spawnBoss(n), 1100);
    }
    if (n === 1) {
      for (let i = 0; i < 2; i++) this.spawnZombieAt(rand(0, TAU2));
      this.pendingSpawns -= 2;
    }
  }

  spawnBoss(n) {
    if (this.state !== 'playing') return;
    const a = rand(0, TAU2);
    const pos = this.findSpawn(a, 720);
    const z = new Zombie(pos.x, pos.y, 'boss', n);
    this.zombies.push(z);
    this.spawnTimer = 2.5;
    Audio.bossRoar();
    this.shake(14);
    UI.banner('WARNUNG', 'DER KOLOSS VON GARATH', 3.2);
  }

  findSpawn(angleBias, minDist = 680) {
    for (let i = 0; i < 60; i++) {
      const a = angleBias + rand(-.7, .7);
      const d = rand(minDist, minDist + 360);
      const x = clamp(this.player.x + Math.cos(a) * d, 80, MAP.w - 80);
      const y = clamp(this.player.y + Math.sin(a) * d, 80, MAP.h - 80);
      if (World.insideBuilding(x, y)) continue;
      if (World.isBlocked(x, y, 22)) continue;
      if (dist2(x, y, this.player.x, this.player.y) < (minDist * .8) ** 2) continue;
      return { x, y };
    }
    const sp = choice(World.spawns);
    return { x: sp[0], y: sp[1] };
  }

  spawnZombieAt(a) {
    const pos = this.findSpawn(a, 620);
    this.spawnZombie(pos.x, pos.y);
    return pos;
  }

  spawnZombie(x, y) {
    const w = this.wave;
    let type = 'walker';
    const r = Math.random();
    if (w >= 3 && r < .16) type = 'brute';
    else if (w >= 2 && r < .50) type = 'runner';
    const lvl = 1 + (w - 1) * .7;
    const z = new Zombie(x, y, type, lvl);
    this.zombies.push(z);
    return z;
  }

  spawnDrops(x, y, count = 1, forceType = null) {
    const types = ['medkit', 'ammo', 'adrenaline', 'speed', 'shield', 'treat'];
    for (let i = 0; i < count; i++) {
      const type = forceType || choice(types);
      const a = rand(0, TAU2), d = rand(12, 34);
      this.pickups.push(new Pickup(x + Math.cos(a) * d, y + Math.sin(a) * d, type));
    }
  }

  addFireBurst(x, y, n = 5) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU2), s = rand(20, 80);
      this.particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r: rand(1, 2.5), life: rand(.15, .35), maxLife: .35, color: 'rgba(255,200,120,', type: 'spark' });
    }
  }
}

input.oldString:
  addFireBurst(x, y, n = 5) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU2), s = rand(20, 80);
      this.particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r: rand(1, 2.5), life: rand(.15, .35), maxLife: .35, color: 'rgba(255,200,120,', type: 'spark' });
    }
  }
}

input.newString:
  addFireBurst(x, y, n = 5) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU2), s = rand(20, 80);
      this.particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r: rand(1, 2.5), life: rand(.15, .35), maxLife: .35, color: 'rgba(255,200,120,', type: 'spark' });
    }
  }

  // ===================== LOOP =====================
  loop(ts) {
    requestAnimationFrame(this.boundLoop);
    const now = ts / 1000;
    if (!this.lastTs) this.lastTs = now;
    let dt = Math.min(now - this.lastTs, .05);
    this.lastTs = now;
    this.time += dt;
    this.fpsSmoothed = lerp(this.fpsSmoothed, 1 / Math.max(.001, now - (this.prevNow || now)), .05);
    this.prevNow = now;
    Input.pollGamepad();

    // global keys
    if (Input.hit('KeyM')) UI.toggleSound();
    if (this.state === 'playing') {
      if (Input.hit('Escape') || Input.hit('KeyP') || Input.pad.start) this.pauseGame();
      else this.update(dt);
    } else if (this.state === 'paused') {
      if (Input.hit('Escape') || Input.hit('KeyP') || Input.pad.start) this.resume();
    } else if (this.state === 'levelup') {
      for (let i = 0; i < 3; i++) if (Input.hit('Digit' + (i + 1)) || Input.hit('Numpad' + (i + 1))) UI.pickCard(i);
    } else if (this.state === 'title') {
      this.updateMenu(dt);
      if (Input.hit('Enter') || Input.hit('Space')) this.startRun();
    } else if (this.state === 'gameover') {
      if (Input.hit('Enter')) this.startRun();
    }

    UI.update(dt, this);
    Input.endFrame();
    this.render();
  }

  updateMenu(dt) {
    this.menuAngle += dt * .07;
    const p = this.player;
    p.walk += dt * 1.2;
    p.angle = damp(p.angle, Math.sin(this.menuAngle) * .6 - .1, 2, dt);
    this.dogs.forEach((d, i) => {
      d.walk += dt * (i ? 2.4 : 1.8);
      d.angle = damp(d.angle, Math.sin(this.menuAngle * 1.3 + i) * .5, 2, dt);
    });
    const targetX = CAMPFIRE.x + Math.cos(this.menuAngle * .55) * 120;
    const targetY = CAMPFIRE.y + Math.sin(this.menuAngle * .42) * 70;
    this.cam.x = damp(this.cam.x, targetX, 1.2, dt);
    this.cam.y = damp(this.cam.y, targetY - 20, 1.2, dt);
    this.cam.zoom = damp(this.cam.zoom, 1.06, 2, dt);
    this.updateParticles(dt);
    this.spawnCampfireParticles(dt);
    this.updateFireflies(dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt);
  }

  pauseGame() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    UI.updatePause(this);
    UI.show('pause');
  }

  resume() {
    if (this.state !== 'paused') return;
    Audio.resume();
    this.state = 'playing';
    UI.show('none');
  }

  // ===================== UPDATE =====================
  update(dt) {
    this.runTime += dt;
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.4);
    this.supplyTimer -= dt;
    this.player.update(dt, this);
    this.dogs.forEach(d => d.update(dt, this));
    for (const z of this.zombies) z.update(dt, this);
    for (const b of this.bullets) b.update(dt, this);
    for (const p of this.pickups) p.update(dt, this);

    this.zombies = this.zombies.filter(z => !z.dead);
    this.bullets = this.bullets.filter(b => !b.dead);
    this.pickups = this.pickups.filter(p => !p.dead);
    this.decals = this.decals.filter(d => d.life === undefined || d.life > 0);

    this.updateWave(dt);
    this.updateInteractions();
    this.updateParticles(dt);
    this.updateFireflies(dt);
    this.spawnCampfireParticles(dt);

    if (this.supplyTimer <= 0) {
      this.supplyTimer = 48 + rand(0, 14);
      const a = rand(0, TAU2);
      for (let i = 0; i < 14; i++) {
        const x = this.player.x + Math.cos(a + i) * 110, y = this.player.y + Math.sin(a + i) * 110;
        if (!World.isBlocked(x, y, 16)) { this.spawnDrops(x, y, 1); this.ring(x, y, 26, 'rgba(255,210,122,'); break; }
      }
    }

    // camera
    const p = this.player;
    const look = 74;
    const aim = this.getAim(p);
    const tx = p.x + Math.cos(aim ?? p.angle) * look;
    const ty = p.y + Math.sin(aim ?? p.angle) * look;
    this.cam.x = damp(this.cam.x, tx, 6, dt);
    this.cam.y = damp(this.cam.y, ty, 6, dt);
    const halfW = this.vw / (2 * this.zoom), halfH = this.vh / (2 * this.zoom);
    this.cam.x = halfW * 2 > MAP.w ? MAP.w / 2 : clamp(this.cam.x, halfW, MAP.w - halfW);
    this.cam.y = halfH * 2 > MAP.h ? MAP.h / 2 : clamp(this.cam.y, halfH, MAP.h - halfH);
    this.cam.zoom = damp(this.cam.zoom, this.zoom, 5, dt);
    this.cam.shake = Math.max(0, this.cam.shake - dt * 26);
    this.afterimages = this.afterimages.filter(a => (a.life -= dt) > 0);
    this.telegraphs = this.telegraphs.filter(t => (t.life -= dt) > 0);
    this.shockwaves = this.shockwaves.filter(s => (s.life -= dt) > 0);
    for (const s of this.shockwaves) s.r = lerp(s.r, s.maxR, 1 - Math.exp(-8 * dt));

    if (p.hp > 0 && p.shield <= 0 && p.hitFlash > 0) { /* handled */ }
  }

  updateWave(dt) {
    if (!this.waveActive) {
      this.intermission -= dt;
      if (this.intermission <= 0) this.startWave(this.wave + 1);
      return;
    }
    const alive = this.zombies.length;
    if (this.pendingSpawns > 0) {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0 && alive < 34 + Math.min(16, this.wave)) {
        const burst = this.pendingSpawns > 4 && Math.random() < .38 ? 2 : 1;
        for (let i = 0; i < burst && this.pendingSpawns > 0; i++) {
          this.spawnZombieAt(rand(0, TAU2));
          this.pendingSpawns--;
        }
        this.spawnTimer = Math.max(.22, 1.02 - this.wave * .04) * rand(.75, 1.25);
      }
    }
    if (this.pendingSpawns <= 0 && this.zombies.length === 0) {
      this.waveActive = false;
      this.intermission = 9;
      this.score += this.wave * 35;
      this.player.heal(this.wave % 5 === 0 ? 30 : 14);
      this.dogs.forEach(d => { if (d.state !== 'downed') d.heal(30); });
      UI.banner(`WELLE ${this.wave}`, 'ÜBERSTANDEN', 2.8);
      UI.toast(`Welle ${this.wave} überstanden · <b>+${this.wave * 35}</b> Punkte`);
      this.spawnDrops(this.player.x + rand(-60, 60), this.player.y + rand(-60, 60), 2);
      Audio.levelup();
    }
  }

  updateInteractions() {
    const p = this.player;
    let best = null, bd = 1e9, kind = null;
    for (const c of this.crates) {
      if (c.opened) continue;
      const d = dist2(p.x, p.y, c.x, c.y);
      if (d < 82 * 82 && d < bd) { bd = d; best = c; kind = 'crate'; }
    }
    for (const d of this.dogs) {
      if (d.state === 'downed') {
        const dd = dist2(p.x, p.y, d.x, d.y);
        if (dd < 74 * 74 && dd < bd) { bd = dd; best = d; kind = 'dog'; }
      }
    }
    this.interactTarget = best;
    this.interactKind = kind;
    if (!best) { UI.prompt(''); return; }
    if (kind === 'crate') {
      const done = best.type === 'weapon' ? 'Waffe nehmen' : 'Vorräte öffnen';
      UI.prompt(`${done} · ${best.label}`);
    } else {
      UI.prompt(`${best.name} wiederbeleben · ${Math.ceil(best.downTimer)}s`);
    }
    if (Input.hit('KeyE') || Input.touch.use || Input.pad.use) {
      if (kind === 'crate') this.openCrate(best);
      else best.revive(this, .6);
      this.interactTarget = null;
      UI.prompt('');
    }
  }

  openCrate(crate) {
    crate.opened = true;
    this.score += 45;
    Audio.pickup();
    this.ring(crate.x, crate.y, 34, 'rgba(255,210,122,');
    this.addFireBurst(crate.x, crate.y, 10);
    if (crate.type === 'weapon') {
      this.player.addWeapon(crate.weapon, this);
      this.floatingText(crate.x, crate.y - 16, crate.label, '#ffd27a');
    } else {
      this.spawnDrops(crate.x, crate.y, 3);
      this.player.heal(20);
      this.toast('VORRÄTE GEFUNDEN');
    }
  }

  // ===================== AIM / LEVEL =====================
  getAim(player) {
    if (!player) return null;
    if (Input.touch.aimActive) return Math.atan2(Input.touch.aimY, Input.touch.aimX);
    if (Input.pad.aimActive) return Math.atan2(Input.pad.aimY, Input.pad.aimX);
    const mouseAim = (Input.mouse.x || !Input.isTouch) && !Input.pad.fire ? null : null;
    const useMouse = !Input.isTouch && !Input.pad.aimActive;
    if (useMouse) {
      const w = this.screenToWorld(Input.mouse.x, Input.mouse.y);
      this.aimWorld = w;
      return Math.atan2(w.y - player.y, w.x - player.x);
    }
    if (Input.pad.fire) {
      let best = null, bd = 560 * 560;
      for (const z of this.zombies) {
        if (z.dead) continue;
        const d = dist2(player.x, player.y, z.x, z.y);
        if (d < bd) { bd = d; best = z; }
      }
      if (best) return Math.atan2(best.y - player.y, best.x - player.x);
      const mv = Math.hypot(Input.pad.moveX, Input.pad.moveY);
      if (mv > .2) return Math.atan2(Input.pad.moveY, Input.pad.moveX);
    }
    if (Input.isTouch) {
      if (player.moving) return player.angle;
      return player.angle;
    }
    return player.angle;
  }

  screenToWorld(sx, sy) {
    return {
      x: (sx - this.vw / 2) / this.cam.zoom + this.cam.x,
      y: (sy - this.vh / 2) / this.cam.zoom + this.cam.y,
    };
  }

  gainXp(n) {
    const p = this.player;
    p.xp += n;
    while (p.xp >= p.xpNext) {
      p.xp -= p.xpNext;
      p.level++;
      p.xpNext = Math.round(90 * Math.pow(1.24, p.level - 1));
      this.pendingLevelUps++;
    }
    if (this.pendingLevelUps > 0 && this.state === 'playing' && !this.leveling) this.openLevelUp();
  }

  makeCards() {
    const pool = this.upgradePool();
    return shuffle(pool).slice(0, 3);
  }

  openLevelUp() {
    this.leveling = true;
    this.state = 'levelup';
    this.cam.shake = 0;
    Audio.levelup();
    const cards = this.makeCards();
    UI.showLevelUp(this.player.level, cards, i => this.pickUpgrade(i, cards));
  }

  pickUpgrade(i, cards) {
    const card = cards[i];
    if (card) card.apply(this);
    this.pendingLevelUps = Math.max(0, this.pendingLevelUps - 1);
    Audio.powerup();
    UI.toast(`<b>${card ? card.title : 'Verbesserung'}</b> gewählt`);
    if (this.pendingLevelUps > 0) {
      setTimeout(() => {
        if (this.state === 'levelup') {
          const next = this.makeCards();
          UI.showLevelUp(this.player.level, next, j => this.pickUpgrade(j, next));
        }
      }, 220);
    } else {
      this.leveling = false;
      this.state = 'playing';
      UI.show('none');
    }
  }

  upgradePool() {
    const p = this.player, lou = this.dogs[0], safi = this.dogs[1];
    return [
      { cat: 'RICK', icon: '✦', title: 'Scharfe Munition', desc: 'Deine Projektile richten 18 % mehr Schaden an.', stat: '+18 % SCHADEN', accent: '#e3a13c', apply: g => { g.player.upgrades.damage *= 1.18; } },
      { cat: 'RICK', icon: '⌁', title: 'Schnellfeuer', desc: 'Der Abzug sitzt lockerer. Erhöht die Feuerrate um 13 %.', stat: '+13 % FEUERRATE', accent: '#e3a13c', apply: g => { g.player.upgrades.fireRate *= 1.13; } },
      { cat: 'RICK', icon: '✚', title: 'Zäher Hund', desc: 'Du hältst mehr aus. +25 max. Leben und sofortige Heilung.', stat: '+25 LEBEN', accent: '#c95a44', apply: g => { g.player.maxHp += 25; g.player.hp = Math.min(g.player.maxHp, g.player.hp + 35); } },
      { cat: 'RICK', icon: '➤', title: 'Federleicht', desc: 'Beweg dich schneller durch den Wald. +8 % Tempo.', stat: '+8 % TEMPO', accent: '#7ec4a0', apply: g => { g.player.upgrades.speed *= 1.08; } },
      { cat: 'RICK', icon: '⟲', title: 'Ausweichrolle', desc: 'Die Ausweichrolle ist 20 % schneller wieder bereit.', stat: '-20 % COOLDOWN', accent: '#7ec4a0', apply: g => { g.player.upgrades.dashCd *= .8; } },
      { cat: 'RICK', icon: '✧', title: 'Panzerbrechend', desc: 'Kugeln durchschlagen einen weiteren Zombie.', stat: '+1 DURCHSCHLAG', accent: '#d18c4a', apply: g => { g.player.upgrades.pierce += 1; } },
      { cat: 'RICK', icon: '◈', title: 'Präzision', desc: 'Treffer ins Ziel verursachen doppelten Schaden. +8 % Kritchance.', stat: '+8 % KRIT', accent: '#e3a13c', apply: g => { g.player.upgrades.crit += .08; } },
      { cat: 'RICK', icon: '⛨', title: 'Feldarzt', desc: 'Nachladen geht 22 % schneller und du regenerierst 2 Leben pro Sekunde.', stat: '+REGEN', accent: '#c95a44', apply: g => { g.player.upgrades.reload *= .78; g.player.upgrades.regen += 2; } },
      { cat: 'RUDEL', icon: '♥', title: 'Rudelpflege', desc: 'Lou und Safi erhalten +25 max. Leben und werden vollständig geheilt.', stat: '+25 HUNDE-LEBEN', accent: '#a8c56c', apply: g => { for (const d of g.dogs) { d.maxHp += 25; d.hp = d.state === 'downed' ? d.hp : d.maxHp; } } },
      { cat: 'LOU', icon: '❖', title: 'Lous Bestie', desc: 'Lou beißt 30 % härter. Der braune Schäferhund wird zur Waffe.', stat: '+30 % LOU-SCHADEN', accent: '#b98853', apply: g => { g.dogs[0].dmg *= 1.3; } },
      { cat: 'SAFI', icon: '❖', title: 'Safis Blitz', desc: 'Safi greift 28 % schneller an und bewegt sich 12 % schneller.', stat: '+28 % SAFI-TEMPO', accent: '#eee7d4', apply: g => { g.dogs[1].attackRate *= .78; g.dogs[1].speed *= 1.12; } },
      { cat: 'RUDEL', icon: '☠', title: 'Bisswunden', desc: 'Beide Hunde verursachen 22 % mehr Schaden.', stat: '+22 % RUDEL-SCHADEN', accent: '#a8c56c', apply: g => { for (const d of g.dogs) d.dmg *= 1.22; } },
      { cat: 'RUDEL', icon: '⇢', title: 'Wachhunde', desc: 'Lou und Safi sind 15 % schneller und wittern Gegner früher.', stat: '+15 % HUNDE-TEMPO', accent: '#a8c56c', apply: g => { for (const d of g.dogs) d.speed *= 1.15; } },
      { cat: 'RICK', icon: '☰', title: 'Notfallversorgung', desc: 'Heilt sofort 50 Leben und füllt etwas Munition auf.', stat: 'SOFORT-HILFE', accent: '#c95a44', apply: g => { g.player.hp = Math.min(g.player.maxHp, g.player.hp + 50); for (const k of Object.keys(g.player.weapons)) { const w = g.player.weapons[k]; if (w.reserve !== Infinity) w.reserve += Math.ceil(WEAPONS[k].reserve * .35); } } },
    ];
  }

  // ===================== COMBAT =====================
  damageZombie(z, dmg, source, crit) {
    if (!z || z.dead) return;
    z.takeDamage(dmg, this, crit, source);
    if (source instanceof Player) { source.stats.hits++; source.stats.dmg += dmg; }
    if (Math.random() < .75) this.floatingText(z.x + rand(-8, 8), z.y - z.r - 8, Math.round(dmg).toString(), crit ? '#ffd27a' : '#e6dfc8', crit ? 15 : 11);
    if (!crit) Audio.hit();
  }

  killZombie(z, source) {
    if (z.dead) return;
    z.dead = true;
    this.kills++;
    this.score += z.score + this.wave * 2;
    const isDog = source instanceof Dog;
    if (source instanceof Player) source.stats.kills++;
    this.gainXp(Math.round(z.xp * (isDog ? .75 : 1)));
    const dogShare = isDog ? source : null;
    for (const d of this.dogs) {
      if (d === dogShare) d.gainXp(Math.round(z.xp * 1.5), this);
      else if (d.state !== 'downed') d.gainXp(Math.round(z.xp * .45), this);
    }
    this.bloodBurst(z.x, z.y, z.isBoss ? 36 : 12, z.angle);
    Audio.kill();
    this.shake(z.isBoss ? 16 : 3);
    if (z.isBoss) {
      this.spawnDrops(z.x, z.y, 5);
      this.shockwaves.push({ x: z.x, y: z.y, r: 20, maxR: 160, life: .7, maxLife: .7, color: 'rgba(255,120,60,' });
      UI.banner('KOLOSS BESIEGT', `WELLE ${this.wave}`, 3);
      Audio.bossRoar();
    }
    // corpse decal
    this.decals.push({ type: 'corpse', x: z.x, y: z.y, angle: z.angle, scale: z.scale, tint: Math.random(), life: undefined });
    if (this.decals.length > 46) this.decals.shift();
    this.decals.push({ type: 'blood', x: z.x, y: z.y, r: rand(8, 18) * z.scale, tint: Math.random() });
    if (this.decals.length > 90) this.decals.shift();
    // drops
    const dropChance = z.isBoss ? 1 : z.type === 'brute' ? .45 : .15;
    if (chance(dropChance)) this.spawnDrops(z.x, z.y, 1, z.type === 'brute' ? choice(['ammo', 'medkit', 'shield']) : null);
    // occasional ammo to avoid dead ends
    if (this.kills % 12 === 0) this.spawnDrops(z.x, z.y, 1, 'ammo');
  }

  bossSlam(boss) {
    this.shake(20);
    Audio.explosion();
    this.shockwaves.push({ x: boss.x, y: boss.y, r: 24, maxR: 190, life: .8, maxLife: .8, color: 'rgba(255,120,60,' });
    this.bloodBurst(boss.x, boss.y, 22, boss.angle);
    const p = this.player;
    if (dist(p.x, p.y, boss.x, boss.y) < 175) p.takeDamage(30, this);
    for (const d of this.dogs) if (dist(d.x, d.y, boss.x, boss.y) < 175) d.takeDamage(24, this);
  }

  telegraph(x, y, r, life) {
    this.telegraphs.push({ x, y, r, life, maxLife: life });
  }

  onPlayerDown() {
    if (this.state !== 'playing') return;
    this.state = 'gameover';
    Audio.bossRoar();
    this.shake(24);
    this.hurtFlash = 1.4;
    const isRecord = UI.saveBest(this.wave, this.score);
    UI.updateGameOver(this, isRecord);
    setTimeout(() => { if (this.state === 'gameover') UI.show('gameover'); }, 700);
  }

  // ===================== EFFECTS =====================
  shake(n) { this.cam.shake = Math.max(this.cam.shake, n); }

  bloodBurst(x, y, n, angle) {
    for (let i = 0; i < n; i++) {
      const a = angle + Math.PI + rand(-.9, .9);
      const s = rand(30, 190);
      this.particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r: rand(1.2, 4), life: rand(.25, .7), maxLife: .7, color: 'rgba(120,24,16,', type: 'blood', vdamp: 4, gravity: 20 });
    }
  }
  sparks(x, y, n, color) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU2), s = rand(30, 140);
      this.particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r: rand(.8, 2), life: rand(.1, .35), maxLife: .35, color, type: 'spark' });
    }
  }
  ring(x, y, r, color) {
    this.shockwaves.push({ x, y, r: r * .2, maxR: r, life: .45, maxLife: .45, color });
  }
  muzzleFlash(x, y, angle, kind) {
    this.addFireBurst(x, y, kind === 'shotgun' ? 8 : 4);
    this.flashLight = { x, y, life: .09, maxLife: .09, r: kind === 'shotgun' ? 190 : 120 };
  }
  damageNumber(x, y, text, color) { this.floatingText(x, y, text, color, 13); }
  floatingText(x, y, text, color = '#e6dfc8', size = 12) {
    this.floatingTexts.push({ x, y, text, color, size, life: .9, maxLife: .9, vy: -34 });
    if (this.floatingTexts.length > 60) this.floatingTexts.shift();
  }
  toast(text, cls) { UI.toast(text, cls); }

  updateParticles(dt) {
    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.vdamp) { const k = Math.exp(-p.vdamp * dt); p.vx *= k; p.vy *= k; }
      if (p.gravity) p.vy += p.gravity * dt;
      if (p.grow) p.r += p.r * p.grow * dt;
    }
    this.particles = this.particles.filter(p => p.life > 0);
    if (this.particles.length > 620) this.particles.splice(0, this.particles.length - 620);
    for (const f of this.floatingTexts) { f.life -= dt; f.y += f.vy * dt; f.vy *= Math.exp(-2.5 * dt); }
    this.floatingTexts = this.floatingTexts.filter(f => f.life > 0);
    if (this.flashLight) { this.flashLight.life -= dt; if (this.flashLight.life <= 0) this.flashLight = null; }
    // fade decals? keep
  }

  updateFireflies(dt) {
    for (const f of this.fireflies) {
      f.p += dt * f.s;
      f.x += Math.cos(f.p) * 6 * dt;
      f.y += Math.sin(f.p * 1.3) * 4 * dt;
    }
  }

  spawnCampfireParticles(dt) {
    if (Math.random() < dt * 22) {
      const x = CAMPFIRE.x + rand(-11, 11), y = CAMPFIRE.y + rand(-6, 6);
      this.particles.push({
        x, y, vx: rand(-8, 8), vy: rand(-55, -25), r: rand(1.4, 4), life: rand(.4, 1.1), maxLife: 1.1,
        color: Math.random() < .4 ? 'rgba(255,220,140,' : 'rgba(255,120,40,', type: 'fire', grow: -.5,
      });
    }
    if (Math.random() < dt * 5) {
      this.particles.push({ x: CAMPFIRE.x + rand(-20, 20), y: CAMPFIRE.y - 10, vx: rand(-6, 6), vy: rand(-26, -12), r: rand(3, 7), life: rand(.9, 1.8), maxLife: 1.8, color: 'rgba(90,85,70,', type: 'smoke', grow: 1.2 });
    }
  }
}

