284:     this.cam.zoom = damp(this.cam.zoom, 1.06, 2, dt);
285:     this.updateParticles(dt);
286:     this.spawnCampfireParticles(dt);
287:     this.updateFireflies(dt);
288:     this.hurtFlash = Math.max(0, this.hurtFlash - dt);
289:   }
