305:   // ===================== UPDATE =====================
306:   update(dt) {
307:     this.runTime += dt;
308:     this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.4);
309:     this.supplyTimer -= dt;
310:     this.player.update(dt, this);
311:     this.dogs.forEach(d => d.update(dt, this));
312:     for (const z of this.zombies) z.update(dt, this);
313:     for (const b of this.bullets) b.update(dt, this);
314:     for (const p of this.pickups) p.update(dt, this);
315: 
316:     this.zombies = this.zombies.filter(z => !z.dead);
317:     this.bullets = this.bullets.filter(b => !b.dead);
318:     this.pickups = this.pickups.filter(p => !p.dead);
319:     this.decals = this.decals.filter(d => d.life === undefined || d.life > 0);
320: 
321:     this.updateWave(dt);
322:     this.updateInteractions();
323:     this.updateParticles(dt);
324:     this.updateFireflies(dt);
325:     this.spawnCampfireParticles(dt);
326: 
327:     if (this.supplyTimer <= 0) {
328:       this.supplyTimer = 48 + rand(0, 14);
329:       const a = rand(0, TAU2);
330:       for (let i = 0; i < 14; i++) {
331:         const x = this.player.x + Math.cos(a + i) * 110, y = this.player.y + Math.sin(a + i) * 110;
332:         if (!World.isBlocked(x, y, 16)) { this.spawnDrops(x, y, 1); this.ring(x, y, 26, 'rgba(255,210,122,'); break; }
333:       }
334:     }
335: 
336:     // camera
337:     const p = this.player;
338:     const look = 74;
339:     const aim = this.getAim(p);
340:     const tx = p.x + Math.cos(aim ?? p.angle) * look;
341:     const ty = p.y + Math.sin(aim ?? p.angle) * look;
342:     this.cam.x = damp(this.cam.x, tx, 6, dt);
343:     this.cam.y = damp(this.cam.y, ty, 6, dt);
344:     const halfW = this.vw / (2 * this.zoom), halfH = this.vh / (2 * this.zoom);
345:     this.cam.x = halfW * 2 > MAP.w ? MAP.w / 2 : clamp(this.cam.x, halfW, MAP.w - halfW);
346:     this.cam.y = halfH * 2 > MAP.h ? MAP.h / 2 : clamp(this.cam.y, halfH, MAP.h - halfH);
347:     this.cam.zoom = damp(this.cam.zoom, this.zoom, 5, dt);
348:     this.cam.shake = Math.max(0, this.cam.shake - dt * 26);
349:     this.afterimages = this.afterimages.filter(a => (a.life -= dt) > 0);
350:     this.telegraphs = this.telegraphs.filter(t => (t.life -= dt) > 0);
351:     this.shockwaves = this.shockwaves.filter(s => (s.life -= dt) > 0);
352:     for (const s of this.shockwaves) s.r = lerp(s.r, s.maxR, 1 - Math.exp(-8 * dt));
353: 
354:     if (p.hp > 0 && p.shield <= 0 && p.hitFlash > 0) { /* handled */ }
355:   }
