357:   updateWave(dt) {
358:     if (!this.waveActive) {
359:       this.intermission -= dt;
360:       if (this.intermission <= 0) this.startWave(this.wave + 1);
361:       return;
362:     }
363:     const alive = this.zombies.length;
364:     if (this.pendingSpawns > 0) {
365:       this.spawnTimer -= dt;
366:       if (this.spawnTimer <= 0 && alive < 34 + Math.min(16, this.wave)) {
367:         const burst = this.pendingSpawns > 4 && Math.random() < .38 ? 2 : 1;
368:         for (let i = 0; i < burst && this.pendingSpawns > 0; i++) {
369:           this.spawnZombieAt(rand(0, TAU2));
370:           this.pendingSpawns--;
371:         }
372:         this.spawnTimer = Math.max(.22, 1.02 - this.wave * .04) * rand(.75, 1.25);
373:       }
374:     }
375:     if (this.pendingSpawns <= 0 && this.zombies.length === 0) {
376:       this.waveActive = false;
377:       this.intermission = 9;
378:       this.score += this.wave * 35;
379:       this.player.heal(this.wave % 5 === 0 ? 30 : 14);
380:       this.dogs.forEach(d => { if (d.state !== 'downed') d.heal(30); });
381:       UI.banner(`WELLE ${this.wave}`, 'ÜBERSTANDEN', 2.8);
382:       UI.toast(`Welle ${this.wave} überstanden · <b>+${this.wave * 35}</b> Punkte`);
383:       this.spawnDrops(this.player.x + rand(-60, 60), this.player.y + rand(-60, 60), 2);
384:       Audio.levelup();
385:     }
386:   }
