388:   updateInteractions() {
389:     const p = this.player;
390:     let best = null, bd = 1e9, kind = null;
391:     for (const c of this.crates) {
392:       if (c.opened) continue;
393:       const d = dist2(p.x, p.y, c.x, c.y);
394:       if (d < 82 * 82 && d < bd) { bd = d; best = c; kind = 'crate'; }
395:     }
396:     for (const d of this.dogs) {
397:       if (d.state === 'downed') {
398:         const dd = dist2(p.x, p.y, d.x, d.y);
399:         if (dd < 74 * 74 && dd < bd) { bd = dd; best = d; kind = 'dog'; }
400:       }
401:     }
402:     this.interactTarget = best;
403:     this.interactKind = kind;
404:     if (!best) { UI.prompt(''); return; }
405:     if (kind === 'crate') {
406:       const done = best.type === 'weapon' ? 'Waffe nehmen' : 'Vorräte öffnen';
407:       UI.prompt(`${done} · ${best.label}`);
408:     } else {
409:       UI.prompt(`${best.name} wiederbeleben · ${Math.ceil(best.downTimer)}s`);
410:     }
411:     if (Input.hit('KeyE') || Input.touch.use || Input.pad.use) {
412:       if (kind === 'crate') this.openCrate(best);
413:       else best.revive(this, .6);
414:       this.interactTarget = null;
415:       UI.prompt('');
416:     }
417:   }
