435:   // ===================== AIM / LEVEL =====================
436:   getAim(player) {
437:     if (!player) return null;
438:     if (Input.touch.aimActive) return Math.atan2(Input.touch.aimY, Input.touch.aimX);
439:     if (Input.pad.aimActive) return Math.atan2(Input.pad.aimY, Input.pad.aimX);
440:     const mouseAim = (Input.mouse.x || !Input.isTouch) && !Input.pad.fire ? null : null;
441:     const useMouse = !Input.isTouch && !Input.pad.aimActive;
442:     if (useMouse) {
443:       const w = this.screenToWorld(Input.mouse.x, Input.mouse.y);
444:       this.aimWorld = w;
445:       return Math.atan2(w.y - player.y, w.x - player.x);
446:     }
447:     if (Input.pad.fire) {
448:       let best = null, bd = 560 * 560;
449:       for (const z of this.zombies) {
450:         if (z.dead) continue;
451:         const d = dist2(player.x, player.y, z.x, z.y);
452:         if (d < bd) { bd = d; best = z; }
453:       }
454:       if (best) return Math.atan2(best.y - player.y, best.x - player.x);
455:       const mv = Math.hypot(Input.pad.moveX, Input.pad.moveY);
456:       if (mv > .2) return Math.atan2(Input.pad.moveY, Input.pad.moveX);
457:     }
458:     if (Input.isTouch) {
459:       if (player.moving) return player.angle;
460:       return player.angle;
461:     }
462:     return player.angle;
463:   }
