465:   screenToWorld(sx, sy) {
466:     return {
467:       x: (sx - this.vw / 2) / this.cam.zoom + this.cam.x,
468:       y: (sy - this.vh / 2) / this.cam.zoom + this.cam.y,
469:     };
470:   }
