472:   gainXp(n) {
473:     const p = this.player;
474:     p.xp += n;
475:     while (p.xp >= p.xpNext) {
476:       p.xp -= p.xpNext;
477:       p.level++;
478:       p.xpNext = Math.round(90 * Math.pow(1.24, p.level - 1));
479:       this.pendingLevelUps++;
480:     }
481:     if (this.pendingLevelUps > 0 && this.state === 'playing' && !this.leveling) this.openLevelUp();
482:   }
