539:   damageZombie(z, dmg, source, crit) {
540:     if (!z || z.dead) return;
541:     z.takeDamage(dmg, this, crit, source);
542:     if (source instanceof Player) { source.stats.hits++; source.stats.dmg += dmg; }
543:     if (Math.random() < .75) this.floatingText(z.x + rand(-8, 8), z.y - z.r - 8, Math.round(dmg).toString(), crit ? '#ffd27a' : '#e6dfc8', crit ? 15 : 11);
544:     if (!crit) Audio.hit();
