547:   killZombie(z, source) {
548:     if (z.dead) return;
549:     z.dead = true;
550:     this.kills++;
551:     this.score += z.score + this.wave * 2;
552:     const isDog = source instanceof Dog;
553:     if (source instanceof Player) source.stats.kills++;
554:     this.gainXp(Math.round(z.xp * (isDog ? .75 : 1)));
555:     const dogShare = isDog ? source : null;
556:     for (const d of this.dogs) {
557:       if (d === dogShare) d.gainXp(Math.round(z.xp * 1.5), this);
558:       else if (d.state !== 'downed') d.gainXp(Math.round(z.xp * .45), this);
559:     }
560:     this.bloodBurst(z.x, z.y, z.isBoss ? 36 : 12, z.angle);
561:     Audio.kill();
562:     this.shake(z.isBoss ? 16 : 3);
563:     if (z.isBoss) {
564:       this.spawnDrops(z.x, z.y, 5);
565:       this.shockwaves.push({ x: z.x, y: z.y, r: 20, maxR: 160, life: .7, maxLife: .7, color: 'rgba(255,120,60,' });
566:       UI.banner('KOLOSS BESIEGT', `WELLE ${this.wave}`, 3);
567:       Audio.bossRoar();
568:     }
569:     // corpse decal
570:     this.decals.push({ type: 'corpse', x: z.x, y: z.y, angle: z.angle, scale: z.scale, tint: Math.random(), life: undefined });
571:     if (this.decals.length > 46) this.decals.shift();
572:     this.decals.push({ type: 'blood', x: z.x, y: z.y, r: rand(8, 18) * z.scale, tint: Math.random() });
573:     if (this.decals.length > 90) this.decals.shift();
574:     // drops
575:     const dropChance = z.isBoss ? 1 : z.type === 'brute' ? .45 : .15;
576:     if (chance(dropChance)) this.spawnDrops(z.x, z.y, 1, z.type === 'brute' ? choice(['ammo', 'medkit', 'shield']) : null);
577:     // occasional ammo to avoid dead ends
578:     if (this.kills % 12 === 0) this.spawnDrops(z.x, z.y, 1, 'ammo');
