636:   updateParticles(dt) {
637:     for (const p of this.particles) {
638:       p.life -= dt;
639:       p.x += p.vx * dt; p.y += p.vy * dt;
640:       if (p.vdamp) { const k = Math.exp(-p.vdamp * dt); p.vx *= k; p.vy *= k; }
641:       if (p.gravity) p.vy += p.gravity * dt;
642:       if (p.grow) p.r += p.r * p.grow * dt;
643:     }
644:     this.particles = this.particles.filter(p => p.life > 0);
645:     if (this.particles.length > 620) this.particles.splice(0, this.particles.length - 620);
646:     for (const f of this.floatingTexts) { f.life -= dt; f.y += f.vy * dt; f.vy *= Math.exp(-2.5 * dt); }
647:     this.floatingTexts = this.floatingTexts.filter(f => f.life > 0);
648:     if (this.flashLight) { this.flashLight.life -= dt; if (this.flashLight.life <= 0) this.flashLight = null; }
649:     // fade decals? keep
650:   }
651: 
652:   updateFireflies(dt) {
653:     for (const f of this.fireflies) {
654:       f.p += dt * f.s;
655:       f.x += Math.cos(f.p) * 6 * dt;
656:       f.y += Math.sin(f.p * 1.3) * 4 * dt;
657:     }
658:   }
