660:   spawnCampfireParticles(dt) {
661:     if (Math.random() < dt * 22) {
662:       const x = CAMPFIRE.x + rand(-11, 11), y = CAMPFIRE.y + rand(-6, 6);
663:       this.particles.push({
664:         x, y, vx: rand(-8, 8), vy: rand(-55, -25), r: rand(1.4, 4), life: rand(.4, 1.1), maxLife: 1.1,
665:         color: Math.random() < .4 ? 'rgba(255,220,140,' : 'rgba(255,120,40,', type: 'fire', grow: -.5,
666:       });
667:     }
668:     if (Math.random() < dt * 5) {
669:       this.particles.push({ x: CAMPFIRE.x + rand(-20, 20), y: CAMPFIRE.y - 10, vx: rand(-6, 6), vy: rand(-26, -12), r: rand(3, 7), life: rand(.9, 1.8), maxLife: 1.8, color: 'rgba(90,85,70,', type: 'smoke', grow: 1.2 });
670:     }
671:   }
672: 
673:   // ===================== RENDER =====================
674:   render() {
675:     const ctx = this.ctx, vw = this.vw, vh = this.vh;
676:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
677:     ctx.clearRect(0, 0, vw, vh);
678:     ctx.fillStyle = '#080d09'; ctx.fillRect(0, 0, vw, vh);
679: 
680:     const sh = this.cam.shake;
681:     const shakeX = sh ? rand(-sh, sh) : 0;
682:     const shakeY = sh ? rand(-sh, sh) : 0;
683:     const camX = this.cam.x + shakeX, camY = this.cam.y + shakeY;
684:     const z = this.cam.zoom;
685:     this.renderCam = { x: camX, y: camY, z };
686: 
687:     // ground (screen-space for 1:1 texture sharpness)
688:     World.drawGround(ctx, { x: camX, y: camY, zoom: z }, vw, vh);
689: 
690:     ctx.save();
691:     ctx.setTransform(this.dpr * z, 0, 0, this.dpr * z, this.dpr * (vw / 2 - camX * z), this.dpr * (vh / 2 - camY * z));
692:     const view = { x: camX, y: camY, w: vw / z, h: vh / z };
693: 
694:     World.drawWater(ctx, this.time);
695:     this.drawDecals(ctx);
696:     this.drawAfterimages(ctx);
697:     this.drawStructures(ctx);
698:     this.drawCrates(ctx);
699:     this.drawCampfireBase(ctx);
700:     for (const p of this.pickups) p.draw(ctx, this.time);
701:     this.drawTelegraphs(ctx);
702:     // low bushes
703:     for (const b of World.bushes) {
704:       if (Math.abs(b.x - camX) < view.w / 2 + 80 && Math.abs(b.y - camY) < view.h / 2 + 80) World.drawBush(ctx, b);
705:     }
706:     this.drawShockwaves(ctx);
707:     this.drawSorted(ctx, camX, camY, view);
708:     this.drawBullets(ctx);
709:     this.drawParticles(ctx);
710:     this.drawFire(ctx);
711:     this.drawFloatingTexts(ctx);
712:     ctx.restore();
713: 
714:     this.renderLighting(camX, camY);
715:     this.drawScreenFx(ctx);
716:   }
717: 
718:   drawSorted(ctx, camX, camY, view) {
719:     const drawables = [];
720:     for (const tree of World.trees) {
721:       if (Math.abs(tree.x - camX) < view.w / 2 + 140 && Math.abs(tree.y - camY) < view.h / 2 + 140) {
722:         drawables.push({ y: tree.y, draw: () => World.drawTree(ctx, tree, this.time) });
723:       }
724:     }
725:     for (const z of this.zombies) {
726:       if (z.dead) continue;
727:       if (Math.abs(z.x - camX) > view.w / 2 + 120 || Math.abs(z.y - camY) > view.h / 2 + 120) continue;
728:       drawables.push({ y: z.y, draw: () => z.draw(ctx, this.time) });
729:     }
730:     for (const d of this.dogs) {
731:       if (Math.abs(d.x - camX) > view.w / 2 + 80 || Math.abs(d.y - camY) > view.h / 2 + 80) continue;
732:       drawables.push({ y: d.y + 2, draw: () => d.draw(ctx, this.time) });
733:     }
734:     if (this.player) drawables.push({ y: this.player.y + 4, draw: () => this.drawPlayer(ctx) });
735:     drawables.sort((a, b) => a.y - b.y);
736:     for (const d of drawables) d.draw();
737:     this.drawMuzzle(ctx);
738:     // dog revive rings
739:     for (const dog of this.dogs) if (dog.state === 'downed') {
740:       ctx.save();
741:       ctx.strokeStyle = 'rgba(214,120,80,.5)'; ctx.lineWidth = 2;
742:       ctx.beginPath(); ctx.arc(dog.x, dog.y, 26 + Math.sin(this.time * 3) * 3, 0, TAU); ctx.stroke();
743:       ctx.restore();
744:     }
745:   }
746: 
747:   drawPlayer(ctx) {
748:     const p = this.player;
749:     p.draw(ctx, this.time);
750:     if (p.shield > 0) {
751:       ctx.save();
752:       ctx.strokeStyle = `rgba(120,200,225,${.22 + Math.sin(this.time * 3) * .06})`;
753:       ctx.lineWidth = 2;
754:       ctx.beginPath(); ctx.arc(p.x, p.y, 24, 0, TAU); ctx.stroke();
755:       ctx.restore();
756:     }
757:   }
758: 
759:   drawMuzzle(ctx) {
760:     const p = this.player;
761:     if (!p || p.muzzle <= 0) return;
762:     const x = p.x + Math.cos(p.angle) * 30, y = p.y + Math.sin(p.angle) * 30;
763:     const a = p.angle;
764:     const big = p.weapon.id === 'shotgun' ? 1.5 : 1;
765:     ctx.save();
766:     ctx.translate(x, y); ctx.rotate(a);
767:     ctx.globalCompositeOperation = 'lighter';
768:     ctx.fillStyle = 'rgba(255,220,140,.9)';
769:     ctx.beginPath();
770:     ctx.moveTo(0, -4 * big); ctx.lineTo(26 * big, 0); ctx.lineTo(0, 4 * big); ctx.lineTo(8 * big, 0); ctx.closePath(); ctx.fill();
771:     ctx.fillStyle = 'rgba(255,150,50,.55)';
772:     ctx.beginPath(); ctx.arc(6, 0, 11 * big, 0, TAU); ctx.fill();
773:     ctx.restore();
774:   }
