776:   // ===================== WORLD LAYERS =====================
777:   drawStructures(ctx) {
778:     // world floor labels
779:     ctx.save();
780:     ctx.globalAlpha = .3;
781:     ctx.fillStyle = '#d9c9a2';
782:     ctx.font = '600 30px Bahnschrift, Arial';
783:     ctx.textAlign = 'center';
784:     ctx.fillText('ZUM ALTEN FORST', 2860, 1908);
785:     ctx.font = '600 16px Bahnschrift, Arial';
786:     ctx.fillText('SEIT 1908', 2860, 1930);
787:     ctx.font = '600 20px Bahnschrift, Arial';
788:     ctx.fillText('ZIVILSCHUTZ', 740, 1290);
789:     ctx.font = '600 15px Bahnschrift, Arial';
790:     ctx.fillText('KIOSK · GARATH', 2170, 740);
791:     ctx.restore();
792: 
793:     // fences
794:     for (const f of World.fences) World.drawFence(ctx, f);
795:     for (const p of World.props) if (p.type === 'rug') World.drawRug(ctx, p);
796:     for (const p of World.props) if (p.type !== 'rug') World.drawProp(ctx, p);
797:     for (const c of World.cars) World.drawCar(ctx, c);
798: 
799:     // walls
800:     for (const w of World.walls) this.drawWall(ctx, w);
801:     // windows / signs
802:     this.drawSigns(ctx);
803:     // lamps
804:     for (const l of World.lights) {
805:       if (l.r < 200) continue;
806:       if (l.x === CAMPFIRE.x && l.y === CAMPFIRE.y) continue;
807:       this.drawLamp(ctx, l);
808:     }
809:   }
