811:   drawWall(ctx, w) {
812:     ctx.save();
813:     ctx.fillStyle = 'rgba(0,0,0,.42)';
814:     ctx.fillRect(w.x + 6, w.y + 8, w.w, w.h);
815:     let base = '#3e4036', light = '#5c5e50', line = 'rgba(20,22,16,.35)';
816:     if (w.mat === 'wood') { base = '#4a3523'; light = '#6b4f34'; line = 'rgba(20,12,6,.4)'; }
817:     if (w.mat === 'concrete') { base = '#47493f'; light = '#666858'; }
818:     if (w.mat === 'brick') { base = '#4e3d32'; light = '#6d5645'; line = 'rgba(24,14,10,.4)'; }
819:     ctx.fillStyle = base; ctx.fillRect(w.x, w.y, w.w, w.h);
820:     ctx.fillStyle = light; ctx.fillRect(w.x, w.y, w.w, 3);
821:     ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.fillRect(w.x, w.y + w.h - 3, w.w, 3);
822:     if (w.mat === 'wood') {
823:       const vert = w.h > w.w;
824:       ctx.strokeStyle = line; ctx.lineWidth = 1;
825:       if (vert) for (let y = w.y + 12; y < w.y + w.h; y += 18) { ctx.beginPath(); ctx.moveTo(w.x + 2, y); ctx.lineTo(w.x + w.w - 2, y); ctx.stroke(); }
826:       else for (let x = w.x + 18; x < w.x + w.w; x += 26) { ctx.beginPath(); ctx.moveTo(x, w.y + 2); ctx.lineTo(x, w.y + w.h - 2); ctx.stroke(); }
827:     } else if (w.mat === 'brick') {
828:       ctx.strokeStyle = line; ctx.lineWidth = 1;
829:       for (let y = w.y + 7; y < w.y + w.h; y += 10) {
830:         ctx.beginPath(); ctx.moveTo(w.x, y); ctx.lineTo(w.x + w.w, y); ctx.stroke();
831:       }
832:     } else {
833:       ctx.fillStyle = 'rgba(180,180,150,.04)';
834:       ctx.fillRect(w.x + 3, w.y + 4, w.w - 6, 2);
835:     }
836:     ctx.restore();
837:   }
