850:     ctx.fillStyle = '#3a2c1c'; ctx.fillRect(sx - 8, sy + 6, 5, 30); ctx.fillRect(sx + 4, sy + 6, 5, 30);
851:     ctx.restore();
852:     // gasthaus hanging sign
