861:   drawLamp(ctx, l) {
862:     ctx.save();
863:     const off = l.flicker > .2 && Math.sin(this.time * 13 + l.x) > .93;
864:     ctx.globalAlpha = off ? .4 : 1;
865:     ctx.fillStyle = 'rgba(0,0,0,.4)';
866:     ctx.beginPath(); ctx.ellipse(l.x + 6, l.y + 9, 11, 5, 0, 0, TAU); ctx.fill();
867:     ctx.fillStyle = '#2c2e28'; ctx.fillRect(l.x - 2, l.y - 6, 5, 16);
868:     ctx.fillStyle = '#43443a'; ctx.fillRect(l.x - 8, l.y - 10, 17, 6);
869:     ctx.fillStyle = off ? '#7a6a44' : '#ffd28a';
870:     ctx.beginPath(); ctx.arc(l.x, l.y - 7, 3.4, 0, TAU); ctx.fill();
871:     ctx.restore();
