879:         ctx.fillStyle = '#2c2416'; ctx.fillRect(c.x - 22, c.y - 16, 44, 32);
880:         ctx.strokeStyle = '#544326'; ctx.strokeRect(c.x - 22, c.y - 16, 44, 32);
881:         ctx.restore();
882:         continue;
883:       }
884:       const pulse = .5 + Math.sin(this.time * 2.6 + c.x) * .2;
885:       ctx.save();
886:       ctx.fillStyle = `rgba(255,210,122,${.05 + pulse * .05})`;
887:       ctx.beginPath(); ctx.arc(c.x, c.y, 38, 0, TAU); ctx.fill();
888:       ctx.fillStyle = 'rgba(0,0,0,.45)'; ctx.beginPath(); ctx.ellipse(c.x + 3, c.y + 17, 24, 9, 0, 0, TAU); ctx.fill();
889:       ctx.fillStyle = '#4d3a22'; roundedBox(ctx, c.x - 24, c.y - 19, 48, 38, 4); ctx.fill();
890:       ctx.fillStyle = c.type === 'weapon' ? '#6d5730' : '#5b4a2e'; roundedBox(ctx, c.x - 21, c.y - 16, 42, 32, 3); ctx.fill();
891:       ctx.strokeStyle = '#2c2112'; ctx.lineWidth = 2;
892:       ctx.beginPath(); ctx.moveTo(c.x - 21, c.y - 16); ctx.lineTo(c.x + 21, c.y + 16); ctx.moveTo(c.x + 21, c.y - 16); ctx.lineTo(c.x - 21, c.y + 16); ctx.stroke();
893:       ctx.fillStyle = 'rgba(255,210,122,.85)';
894:       if (c.type === 'weapon') {
895:         ctx.fillRect(c.x - 11, c.y - 3, 22, 4); ctx.fillRect(c.x + 3, c.y + 1, 4, 5);
896:       } else {
897:         ctx.fillRect(c.x - 8, c.y - 8, 16, 16);
898:         ctx.fillStyle = '#4d3a22'; ctx.fillRect(c.x - 2, c.y - 5, 4, 10); ctx.fillRect(c.x - 5, c.y - 2, 10, 4);
899:       }
900:       ctx.restore();
901:     }
902:   }
