904:   drawCampfireBase(ctx) {
905:     ctx.save();
906:     // stones
907:     for (let i = 0; i < 11; i++) {
908:       const a = i / 11 * TAU;
909:       ctx.fillStyle = i % 2 ? '#4a4a40' : '#3f4037';
910:       ctx.beginPath(); ctx.ellipse(CAMPFIRE.x + Math.cos(a) * 24, CAMPFIRE.y + Math.sin(a) * 20, 7, 5, a, 0, TAU); ctx.fill();
911:     }
912:     // logs
913:     ctx.save(); ctx.translate(CAMPFIRE.x, CAMPFIRE.y);
914:     ctx.rotate(.4); ctx.fillStyle = '#4c3520'; ctx.fillRect(-17, -5, 34, 10);
915:     ctx.rotate(-.9); ctx.fillStyle = '#553b22'; ctx.fillRect(-15, -4, 30, 9);
916:     ctx.fillStyle = 'rgba(255,140,60,.35)'; ctx.beginPath(); ctx.ellipse(0, 0, 14, 9, 0, 0, TAU); ctx.fill();
917:     ctx.restore();
918:     // sandbags / supplies near camp
919:     ctx.fillStyle = '#4a3a26'; ctx.fillRect(CAMPFIRE.x + 62, CAMPFIRE.y + 36, 30, 20);
920:     ctx.restore();
921:   }
922: 
923:   drawFire(ctx) {
924:     const t = this.time;
925:     const x = CAMPFIRE.x, y = CAMPFIRE.y - 4;
926:     ctx.save();
927:     ctx.globalCompositeOperation = 'lighter';
928:     const flick = .8 + Math.sin(t * 9) * .1 + Math.sin(t * 17) * .05;
929:     for (let i = 0; i < 3; i++) {
930:       const h = (22 + i * 8) * flick;
931:       const w = 15 - i * 3;
932:       const sway = Math.sin(t * 6 + i) * 4;
933:       const g = ctx.createLinearGradient(x, y, x, y - h);
934:       g.addColorStop(0, 'rgba(255,170,50,.55)');
935:       g.addColorStop(.6, `rgba(255,${120 + i * 30},30,.32)`);
936:       g.addColorStop(1, 'rgba(255,220,150,0)');
937:       ctx.fillStyle = g;
938:       ctx.beginPath();
939:       ctx.moveTo(x - w, y);
940:       ctx.quadraticCurveTo(x - w * .4 + sway, y - h * .6, x + sway * .7, y - h);
941:       ctx.quadraticCurveTo(x + w * .5 + sway, y - h * .5, x + w, y);
942:       ctx.closePath(); ctx.fill();
943:     }
944:     ctx.fillStyle = 'rgba(255,210,120,.7)';
945:     ctx.beginPath(); ctx.ellipse(x, y - 4, 12, 7, 0, 0, TAU); ctx.fill();
946:     ctx.restore();
947:   }
948: 
949:   drawTelegraphs(ctx) {
950:     for (const t of this.telegraphs) {
951:       const k = 1 - t.life / t.maxLife;
952:       ctx.save();
953:       ctx.strokeStyle = `rgba(230,90,50,${.35 + Math.sin(this.time * 12) * .15})`;
954:       ctx.fillStyle = `rgba(210,60,35,${.05 + k * .1})`;
955:       ctx.lineWidth = 3;
956:       ctx.beginPath(); ctx.arc(t.x, t.y, t.r, 0, TAU); ctx.fill(); ctx.stroke();
957:       ctx.strokeStyle = 'rgba(255,160,100,.7)'; ctx.lineWidth = 2;
958:       ctx.beginPath(); ctx.arc(t.x, t.y, t.r * k, 0, TAU); ctx.stroke();
959:       ctx.restore();
960:     }
961:   }
962: 
963:   drawShockwaves(ctx) {
964:     for (const s of this.shockwaves) {
965:       const a = clamp(s.life / s.maxLife, 0, 1);
966:       ctx.save();
967:       ctx.strokeStyle = s.color + (a * .7) + ')';
968:       ctx.lineWidth = 3 + (1 - a) * 5;
969:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, TAU); ctx.stroke();
970:       ctx.restore();
971:     }
972:   }
973: 
974:   drawDecals(ctx) {
975:     for (const d of this.decals) {
976:       if (d.type === 'blood') {
977:         ctx.save();
978:         ctx.fillStyle = `rgba(66,16,12,${.25 + d.tint * .25})`;
979:         ctx.beginPath(); ctx.ellipse(d.x, d.y, d.r, d.r * .65, d.tint * TAU, 0, TAU); ctx.fill();
980:         ctx.restore();
981:       } else if (d.type === 'corpse') {
982:         ctx.save();
983:         ctx.translate(d.x, d.y); ctx.rotate(d.angle); ctx.scale(d.scale, d.scale);
984:         ctx.globalAlpha = .85;
985:         ctx.fillStyle = 'rgba(5,7,5,.4)'; ctx.beginPath(); ctx.ellipse(2, 4, 22, 10, 0, 0, TAU); ctx.fill();
986:         ctx.fillStyle = d.tint > .5 ? '#41453a' : '#46392f';
987:         ctx.beginPath(); ctx.ellipse(0, 0, 18, 8, 0, 0, TAU); ctx.fill();
988:         ctx.fillStyle = '#6f6f5c'; ctx.beginPath(); ctx.arc(17, -1, 5.5, 0, TAU); ctx.fill();
989:         ctx.strokeStyle = '#3a392e'; ctx.lineWidth = 4; ctx.lineCap = 'round';
990:         ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-25, -13); ctx.moveTo(-10, 5); ctx.lineTo(-23, 12); ctx.stroke();
991:         ctx.fillStyle = 'rgba(80,20,14,.55)'; ctx.beginPath(); ctx.ellipse(2, 2, 17, 7, .2, 0, TAU); ctx.fill();
992:         ctx.restore();
993:       }
994:     }
995:   }
996: 
997:   drawAfterimages(ctx) {
998:     for (const a of this.afterimages) {
999:       ctx.save();
1000:       ctx.globalAlpha = a.life * .6;
1001:       ctx.translate(a.x, a.y); ctx.rotate(a.a);
1002:       ctx.fillStyle = 'rgba(180,200,170,.3)';
1003:       ctx.beginPath(); ctx.ellipse(0, 0, 16, 12, 0, 0, TAU); ctx.fill();
1004:       ctx.restore();
1005:     }
1006:   }
1007: 
1008:   drawBullets(ctx) {
1009:     ctx.save();
1010:     ctx.globalCompositeOperation = 'lighter';
1011:     for (const b of this.bullets) {
1012:       ctx.strokeStyle = b.kind === 'shotgun' ? 'rgba(255,200,120,.55)' : 'rgba(255,225,150,.75)';
1013:       ctx.lineWidth = b.kind === 'rifle' ? 2.4 : 1.5;
1014:       ctx.beginPath(); ctx.moveTo(b.px, b.py); ctx.lineTo(b.x, b.y); ctx.stroke();
1015:       ctx.fillStyle = 'rgba(255,240,190,.9)';
1016:       ctx.beginPath(); ctx.arc(b.x, b.y, 1.8, 0, TAU); ctx.fill();
1017:     }
1018:     ctx.restore();
1019:   }
1020: 
1021:   drawParticles(ctx) {
1022:     for (const p of this.particles) {
1023:       const a = clamp(p.life / p.maxLife, 0, 1);
1024:       ctx.save();
1025:       ctx.fillStyle = p.color + a + ')';
1026:       if (p.type === 'shell') {
1027:         ctx.translate(p.x, p.y); ctx.rotate(p.life * 20);
1028:         ctx.fillRect(-1.8, -1, 3.6, 2);
1029:       } else if (p.type === 'spark') {
1030:         ctx.globalCompositeOperation = 'lighter';
1031:         ctx.fillRect(p.x - p.r / 2, p.y - p.r / 2, p.r, p.r);
1032:       } else if (p.type === 'smoke') {
1033:         ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, TAU); ctx.fill();
1034:       } else if (p.type === 'fire') {
1035:         ctx.globalCompositeOperation = 'lighter';
1036:         ctx.beginPath(); ctx.arc(p.x, p.y, p.r * (0.5 + a * .8), 0, TAU); ctx.fill();
1037:       } else {
1038:         ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, TAU); ctx.fill();
1039:       }
1040:       ctx.restore();
1041:     }
1042:   }
1043: 
1044:   drawFloatingTexts(ctx) {
1045:     ctx.save();
1046:     ctx.textAlign = 'center';
1047:     for (const f of this.floatingTexts) {
1048:       const a = clamp(f.life / f.maxLife, 0, 1);
1049:       ctx.globalAlpha = a;
1050:       ctx.font = `bold ${f.size}px Bahnschrift, Arial`;
1051:       ctx.fillStyle = 'rgba(0,0,0,.65)';
1052:       ctx.fillText(f.text, f.x + 1, f.y + 1);
1053:       ctx.fillStyle = f.color;
1054:       ctx.fillText(f.text, f.x, f.y);
1055:     }
1056:     ctx.restore();
1057:   }
