1059:   // ===================== LIGHTING =====================
1060:   renderLighting(camX, camY) {
1061:     const lc = this.lightCtx, lw = this.lightCanvas.width, lh = this.lightCanvas.height;
1062:     const ls = this.lightScale;
1063:     const z = this.cam.zoom * ls;
1064:     const ox = this.vw / 2 * ls, oy = this.vh / 2 * ls;
1065:     lc.setTransform(1, 0, 0, 1, 0, 0);
1066:     lc.globalCompositeOperation = 'source-over';
